import { useState } from 'react'
import {
 createBlankFixedAssetFormDraft, createBlankProductionCostFormDraft,
 createBlankSalesProductFormDraft, createBlankWorkingCapitalComponentFormDraft,
 createBlankLoanFacilityFormDraft, createBlankCppCpsTraceItem, createBlankSalesTaxLedgerFormDraft, createBlankValueAddedPeriodFormDraft, createBlankValueAddedInputFormDraft, createBlankValueAddedInvestmentFormDraft, createBlankCostCentreInventoryMovementFormDraft, createBlankInventoryStageTransferFormDraft, createBlankProductionBridgeEvidenceFormDraft, type ProductionBridgeEvidenceFormDraft, type ProductionBridgeLinkFormDraft, type ProjectModelFinancialFormDrafts,
 type FixedAssetFormDraft, type ProductionCostFormDraft,
 type WorkingCapitalComponentFormDraft, type LoanFacilityFormDraft, type CostCentreFormDraft, type ValueAddedPeriodFormDraft, type ValueAddedInputFormDraft, type ValueAddedInvestmentFormDraft,
 validateProjectModelFinancialFormDrafts
} from './projectModelFormDrafts'
import { deriveQuantityPriceTotal, type CommonFinancialItemMetadata } from './projectModelSchema'
import ProjectModelHelpCoveragePanel from './ProjectModelHelpCoveragePanel'
import type { ProjectFoundation, ProjectCalendarPeriod } from './projectFoundation'
import type { CppCpsTraceItem } from './cppCpsCostTraceability'
import { resolveLoanFacilityCurrency } from '../steel/foreignCurrencyTranslation'
import { buildProductionBridgeDraftsFromSalesProduct, upsertProductionBridgeTransferDrafts, type ProductionStageTransferEvidence } from './inventoryProductionFlow'

type Props={value:ProjectModelFinancialFormDrafts;onChange:(value:ProjectModelFinancialFormDrafts)=>void;language?:'fa'|'en';foundation?:ProjectFoundation;projectPeriods?:ProjectCalendarPeriod[]}
const parseNumber=(value:string):number|null=>value.trim()===''?null:Number.isFinite(Number(value))?Number(value):null
function NumberField({label,value,onChange,unit}:{label:string;value:number|null;onChange:(value:number|null)=>void;unit?:string}) {
 return <label className="fw-field"><span>{label}{unit?' ('+unit+')':''}</span><input type="number" step="any" value={value??''} onChange={e=>onChange(parseNumber(e.target.value))}/></label>
}
function TextField({label,value,onChange,type='text'}:{label:string;value:string;onChange:(value:string)=>void;type?:string}) {
 return <label className="fw-field"><span>{label}</span><input type={type} value={value} onChange={e=>onChange(e.target.value)}/></label>
}

function MetadataFields({metadata,onChange,language}:{metadata:CommonFinancialItemMetadata;onChange:(value:CommonFinancialItemMetadata)=>void;language:'fa'|'en'}) {
 const t=(fa:string,en:string)=>language==='en'?en:fa
 return <div className="fw-grid">
  <TextField label={t('کد ارز','Currency code')} value={metadata.currencyCode??''} onChange={v=>onChange({...metadata,currencyCode:v||null})}/>
  <label className="fw-field"><span>{t('مبدأ تأمین','Market origin')}</span><select value={metadata.marketOrigin??''} onChange={e=>onChange({...metadata,marketOrigin:(e.target.value||null) as CommonFinancialItemMetadata['marketOrigin']})}><option value="">{t('انتخاب','Select')}</option><option value="local">{t('داخلی','Local')}</option><option value="foreign">{t('خارجی','Foreign')}</option></select></label>
  <NumberField label={t('تعدیل قیمت','Price escalation')} value={metadata.escalationPercent} unit="%" onChange={v=>onChange({...metadata,escalationPercent:v})}/>
  <TextField label={t('مرکز هزینه','Cost centre ID')} value={metadata.costCentreId??''} onChange={v=>onChange({...metadata,costCentreId:v||null})}/>
  <TextField label={t('ملاحظات','Remarks')} value={metadata.remarks} onChange={v=>onChange({...metadata,remarks:v})}/>
 </div>
}

function ProductionBridgeLinkFields({label,value,onChange,language}:{label:string;value:ProductionBridgeLinkFormDraft;onChange:(value:ProductionBridgeLinkFormDraft)=>void;language:'fa'|'en'}) {
 const t=(fa:string,en:string)=>language==='en'?en:fa
 return <div className="fw-validation" style={{padding:10,marginTop:8}}>
  <strong>{label}</strong>
  <div className="fw-grid">
   <TextField label={t('شناسه محصول مبدأ','Source product ID')} value={value.sourceProductId} onChange={v=>onChange({...value,sourceProductId:v})}/>
   <TextField label={t('شناسه محصول مقصد','Destination product ID')} value={value.destinationProductId} onChange={v=>onChange({...value,destinationProductId:v})}/>
   <TextField label={t('مرکز هزینه مبدأ','Source cost centre')} value={value.sourceCostCentreId} onChange={v=>onChange({...value,sourceCostCentreId:v})}/>
   <TextField label={t('مرکز هزینه مقصد','Destination cost centre')} value={value.destinationCostCentreId} onChange={v=>onChange({...value,destinationCostCentreId:v})}/>
   <TextField label={t('واحد مبدأ','Source unit')} value={value.sourceUnit} onChange={v=>onChange({...value,sourceUnit:v})}/>
   <TextField label={t('واحد مقصد','Destination unit')} value={value.destinationUnit} onChange={v=>onChange({...value,destinationUnit:v})}/>
   <NumberField label={t('ضریب تبدیل','Conversion factor')} value={value.conversionFactor} onChange={v=>onChange({...value,conversionFactor:v})}/>
  </div>
 </div>
}
export default function ProjectModelFinancialFormsPanel({value,onChange,language='fa',foundation,projectPeriods=[]}:Props) {
 const en=language==='en'
 const t=(fa:string,english:string)=>en?english:fa
 const errors=validateProjectModelFinancialFormDrafts(value)
 const patchAsset=(id:string,patch:Partial<FixedAssetFormDraft>)=>onChange({...value,assets:value.assets.map(x=>x.id===id?{...x,...patch}:x)})
 const patchCost=(id:string,patch:Partial<ProductionCostFormDraft>)=>onChange({...value,productionCosts:value.productionCosts.map(x=>x.id===id?{...x,...patch}:x)})
 const patchSales=(index:number,patch:Partial<(typeof value.sales)[number]>)=>onChange({...value,sales:value.sales.map((x,i)=>i===index?{...x,...patch}:x)})

 const [productionBridgeErrors,setProductionBridgeErrors]=useState<Record<number,string>>({})
 const patchProductionBridgeEvidence=(salesIndex:number,periodIndex:number,patch:Partial<ProductionBridgeEvidenceFormDraft>)=>{
  const sale=value.sales[salesIndex];if(!sale)return
  const periods=sale.periods.map((period,index)=>index===periodIndex?{...period,productionBridgeEvidence:{...createBlankProductionBridgeEvidenceFormDraft(),...period.productionBridgeEvidence,...patch}}:period)
  patchSales(salesIndex,{periods})
 }
 const generateProductionBridge=(salesIndex:number)=>{
  const sale=value.sales[salesIndex];if(!sale)return
  try{
   const evidence=sale.periods.map((period,index)=>({...period.productionBridgeEvidence,period:index+1})) as ProductionStageTransferEvidence[]
   const generated=buildProductionBridgeDraftsFromSalesProduct(sale,evidence)
   const existing=value.inventoryStageTransfers??[]
   onChange({...value,inventoryStageTransfers:upsertProductionBridgeTransferDrafts(existing,generated)})
   setProductionBridgeErrors(current=>({...current,[salesIndex]:''}))
  }catch(error){
   setProductionBridgeErrors(current=>({...current,[salesIndex]:error instanceof Error?error.message:String(error)}))
  }
 }
 const patchWorking=(id:string,patch:Partial<WorkingCapitalComponentFormDraft>)=>onChange({...value,workingCapital:value.workingCapital.map(x=>x.id===id?{...x,...patch}:x)})
 const salesTaxLedger=value.salesTaxLedger??createBlankSalesTaxLedgerFormDraft()
 const patchSalesTaxLedger=(patch:Partial<typeof salesTaxLedger>)=>onChange({...value,salesTaxLedger:{...salesTaxLedger,...patch}})
 const patchValueAddedPeriod=(period:number,patch:Partial<ValueAddedPeriodFormDraft>)=>{
  const current=value.economic.valueAddedPeriods??[]
  const existing=current.find(x=>x.period===period)??createBlankValueAddedPeriodFormDraft(period)
  onChange({...value,economic:{...value.economic,valueAddedPeriods:[...current.filter(x=>x.period!==period),{...existing,...patch}]}})
 }
 const patchLoan=(id:string,patch:Partial<LoanFacilityFormDraft>)=>onChange({...value,loans:value.loans.map(x=>x.id===id?{...x,...patch}:x)})
 const costCentres=value.costCentres??[]
 const patchCostCentre=(id:string,patch:Partial<CostCentreFormDraft>)=>onChange({...value,costCentres:costCentres.map(x=>x.id===id?{...x,...patch}:x)})
 const addCostCentre=()=>onChange({...value,costCentres:[...costCentres,{id:crypto.randomUUID(),name:'',type:null,description:'',allocationBasis:null,manualDriverName:'',manualDriverUnit:'',driverRows:[]}]})
 const traceItems=value.cppCpsTraceItems??[]
 const patchTrace=(id:string,patch:Partial<CppCpsTraceItem>)=>onChange({...value,cppCpsTraceItems:traceItems.map(x=>x.id===id?{...x,...patch}:x)})
 const patchTraceSource=(id:string,patch:Partial<CppCpsTraceItem['source']>)=>{
  const item=traceItems.find(x=>x.id===id);if(!item)return
  const source={...item.source,...patch}
  const verified=Boolean(source.reference.trim()&&source.description.trim()&&source.reliability!=='unverified')
  patchTrace(id,{source:{...source,status:verified?'verified':'unverified'},...(verified?{}:{baseCostCoverage:'unverified',periodAmounts:item.periodAmounts.map(()=>null),baseCoveredAmounts:item.baseCoveredAmounts.map(()=>null)})})
 }
 const addTrace=()=>onChange({...value,cppCpsTraceItems:[...traceItems,createBlankCppCpsTraceItem(crypto.randomUUID(),projectPeriods.length)]})

 const patchAssetAcquisition=(assetId:string,index:number,field:'quantity'|'unitPrice'|'total',next:number|null)=>{
  const asset=value.assets.find(x=>x.id===assetId);if(!asset)return
  const rows=asset.acquisitionPeriods.map((row,i)=>{if(i!==index)return row;const derived=deriveQuantityPriceTotal({...row,[field]:next});return {...row,...derived}})
  patchAsset(assetId,{acquisitionPeriods:rows})
 }
 const patchCostStandard=(costId:string,field:'standardQuantity'|'standardUnitPrice'|'standardTotal',next:number|null)=>{
  const cost=value.productionCosts.find(x=>x.id===costId);if(!cost)return
  const derived=deriveQuantityPriceTotal({quantity:field==='standardQuantity'?next:cost.standardQuantity,unitPrice:field==='standardUnitPrice'?next:cost.standardUnitPrice,total:field==='standardTotal'?next:cost.standardTotal})
  patchCost(costId,{standardQuantity:derived.quantity,standardUnitPrice:derived.unitPrice,standardTotal:derived.total})
 }
 const patchCostAdjustment=(costId:string,index:number,field:'quantity'|'unitPrice'|'total',next:number|null)=>{
  const cost=value.productionCosts.find(x=>x.id===costId);if(!cost)return
  patchCost(costId,{adjustments:cost.adjustments.map((row,i)=>{if(i!==index)return row;const derived=deriveQuantityPriceTotal({...row,[field]:next});return {...row,...derived}})})
 }
 const addAsset=()=>onChange({...value,assets:[...value.assets,createBlankFixedAssetFormDraft(crypto.randomUUID())]})
 const addCost=()=>onChange({...value,productionCosts:[...value.productionCosts,createBlankProductionCostFormDraft(crypto.randomUUID())]})
 const addSales=()=>onChange({...value,sales:[...value.sales,createBlankSalesProductFormDraft('')]})
 const addWorking=()=>onChange({...value,workingCapital:[...value.workingCapital,createBlankWorkingCapitalComponentFormDraft(crypto.randomUUID())]})
 const addLoan=()=>onChange({...value,loans:[...value.loans,createBlankLoanFacilityFormDraft(crypto.randomUUID())]})
 return <section className="fw-card" style={{marginTop:16}}>
  <h3>{t('فرم‌های پایه مالی پروژه','Core project financial input forms')}</h3>
  <p className="fw-hint">{t('تمام مقادیر این فرم‌ها خالی شروع می‌شوند. داده‌های واردنشده به‌عنوان صفر یا مقدار پیش‌فرض تلقی نمی‌شوند.','All values start blank. Missing entries are not interpreted as zero or implicit defaults.')}</p>
  <div className="fw-card">
   <h4>{t('۱. دفتر دارایی و استهلاک','1. Asset register and depreciation')}</h4>
   {value.assets.map((asset)=><div className="fw-validation" key={asset.id} style={{marginTop:10,padding:12}}>
    <div className="fw-grid"><TextField label={t('شرح دارایی','Asset description')} value={asset.metadata.description} onChange={v=>patchAsset(asset.id,{metadata:{...asset.metadata,description:v}})}/><label className="fw-field"><span>{t('مبنای شروع استهلاک','Depreciation start convention')}</span><select value={asset.depreciation.startMode??''} onChange={e=>patchAsset(asset.id,{depreciation:{...asset.depreciation,startMode:(e.target.value||null) as FixedAssetFormDraft['depreciation']['startMode']}})}><option value="">{t('انتخاب','Select')}</option><option value="production-start">{t('شروع بهره‌برداری','Production start')}</option><option value="specified-date">{t('تاریخ مشخص','Specified date')}</option></select></label><TextField label={t('تاریخ شروع استهلاک','Depreciation start date')} value={asset.depreciation.startDate} type="date" onChange={v=>patchAsset(asset.id,{depreciation:{...asset.depreciation,startDate:v}})}/><NumberField label={t('ماه‌های سال اول استهلاک','Months in first depreciation year')} value={asset.depreciation.firstDepreciationYearMonths} unit={t('ماه','months')} onChange={v=>patchAsset(asset.id,{depreciation:{...asset.depreciation,firstDepreciationYearMonths:v}})}/><label className="fw-field"><span>{t('روش استهلاک','Depreciation method')}</span><select value={asset.depreciation.method??''} onChange={e=>patchAsset(asset.id,{depreciation:{...asset.depreciation,method:(e.target.value||null) as FixedAssetFormDraft['depreciation']['method']}})}><option value="">{t('انتخاب روش','Select method')}</option><option value="linear-to-zero">{t('خط مستقیم با تعدیل نهایی ارزش اسقاط','Linear to Zero')}</option><option value="linear-to-scrap">{t('خط مستقیم تا اسقاط','Straight line to scrap')}</option><option value="accelerated-declining-balance">{t('نزولی شتاب‌یافته','Accelerated declining balance')}</option><option value="sum-of-years-digits">{t('مجموع سنوات','Sum of years digits')}</option></select></label><NumberField label={t('عمر مفید','Useful life')} value={asset.depreciation.usefulLifeMonths} unit={t('ماه','months')} onChange={v=>patchAsset(asset.id,{depreciation:{...asset.depreciation,usefulLifeMonths:v}})}/><NumberField label={t('نرخ استهلاک','Depreciation rate')} value={asset.depreciation.ratePercent} unit="%" onChange={v=>patchAsset(asset.id,{depreciation:{...asset.depreciation,ratePercent:v}})}/><NumberField label={t('ارزش اسقاط نسبت به بهای دارایی','Salvage value as % of cost')} value={asset.depreciation.salvagePercent} unit="%" onChange={v=>patchAsset(asset.id,{depreciation:{...asset.depreciation,salvagePercent:v}})}/></div>
    {asset.depreciation.method==='sum-of-years-digits'&&((asset.depreciation.usefulLifeMonths??0)%12!==0||(asset.depreciation.firstDepreciationYearMonths!==null&&asset.depreciation.firstDepreciationYearMonths!==12))&&<p className="fw-hint" role="alert">{t('فرمول مجموع سنوات با عمر غیرصحیح یا سال اول ناقص هنوز در موتور محاسبات فعال نیست؛ برای جلوگیری از خروجی نادرست، تا تکمیل الگوریتم مرجع محاسبه نمی‌شود.','Partial-year Sum of Years Digits is not yet enabled in the calculation engine; it is guarded to avoid an unverified result.')}</p>}
    <MetadataFields metadata={asset.metadata} language={language} onChange={metadata=>patchAsset(asset.id,{metadata})}/>
    <h5>{t('برنامه تحصیل دارایی','Asset acquisition schedule')}</h5>
    {asset.acquisitionPeriods.map((row,j)=><div className="fw-grid" key={j}><TextField label={t('تاریخ','Date')} value={row.period} type="date" onChange={v=>patchAsset(asset.id,{acquisitionPeriods:asset.acquisitionPeriods.map((x,k)=>k===j?{...x,period:v}:x)})}/><NumberField label={t('تعداد','Quantity')} value={row.quantity} onChange={v=>patchAssetAcquisition(asset.id,j,'quantity',v)}/><NumberField label={t('قیمت واحد','Unit price')} value={row.unitPrice} onChange={v=>patchAssetAcquisition(asset.id,j,'unitPrice',v)}/><NumberField label={t('جمع','Total')} value={row.total} onChange={v=>patchAssetAcquisition(asset.id,j,'total',v)}/></div>)}
    <button type="button" className="secondary-button" onClick={()=>patchAsset(asset.id,{acquisitionPeriods:[...asset.acquisitionPeriods,{period:'',quantity:null,unitPrice:null,total:null}]})}>{t('افزودن ردیف تحصیل','Add acquisition row')}</button>{asset.disposal&&<div className="fw-grid"><TextField label={t('تاریخ واگذاری/اسقاط','Disposal date')} value={asset.disposal.date} type="date" onChange={v=>patchAsset(asset.id,{disposal:{...asset.disposal!,date:v}})}/><NumberField label={t('عواید واگذاری','Disposal proceeds')} value={asset.disposal.proceeds} onChange={v=>patchAsset(asset.id,{disposal:{...asset.disposal!,proceeds:v}})}/></div>}<button type="button" className="secondary-button" onClick={()=>patchAsset(asset.id,{disposal:asset.disposal?null:{date:'',proceeds:null}})}>{asset.disposal?t('حذف رویداد واگذاری','Remove disposal'):t('ثبت واگذاری/اسقاط','Add disposal')}</button>
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,assets:value.assets.filter(x=>x.id!==asset.id)})}>{t('حذف دارایی','Remove asset')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={addAsset}>{t('افزودن دارایی','Add asset')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۲. هزینه‌های مستقیم و غیرمستقیم','2. Direct and indirect costs')}</h4>
   {value.productionCosts.map(cost=><div className="fw-validation" key={cost.id} style={{marginTop:10,padding:12}}>
    <div className="fw-grid"><TextField label={t('شرح قلم هزینه','Cost item description')} value={cost.metadata.description} onChange={v=>patchCost(cost.id,{metadata:{...cost.metadata,description:v}})}/><label className="fw-field"><span>{t('طبقه‌بندی','Classification')}</span><select value={cost.classification??''} onChange={e=>patchCost(cost.id,{classification:(e.target.value||null) as ProductionCostFormDraft['classification']})}><option value="">{t('انتخاب','Select')}</option><option value="direct">{t('مستقیم','Direct')}</option><option value="indirect">{t('غیرمستقیم','Indirect')}</option></select></label><TextField label={t('شناسه محصول','Product ID')} value={cost.productId??''} onChange={v=>patchCost(cost.id,{productId:v||null})}/><label className="fw-field"><span>{t('مبنای محاسبه','Cost basis')}</span><select value={cost.basis??''} onChange={e=>patchCost(cost.id,{basis:(e.target.value||null) as ProductionCostFormDraft['basis']})}><option value="">{t('انتخاب','Select')}</option><option value="nominal-capacity">{t('ظرفیت اسمی','Nominal capacity')}</option><option value="per-unit-output">{t('هر واحد محصول','Per unit of output')}</option><option value="period-adjustments">{t('تعدیلات دوره‌ای','Period adjustments')}</option></select></label><NumberField label={t('مقدار استاندارد','Standard quantity')} value={cost.standardQuantity} onChange={v=>patchCostStandard(cost.id,'standardQuantity',v)}/><NumberField label={t('قیمت واحد','Unit price')} value={cost.standardUnitPrice} onChange={v=>patchCostStandard(cost.id,'standardUnitPrice',v)}/><NumberField label={t('جمع استاندارد','Standard total')} value={cost.standardTotal} onChange={v=>patchCostStandard(cost.id,'standardTotal',v)}/><NumberField label={t('ظرفیت اسمی','Nominal capacity')} value={cost.nominalCapacity} onChange={v=>patchCost(cost.id,{nominalCapacity:v})}/><NumberField label={t('سهم ثابت','Fixed share')} value={cost.fixedPercent} unit="%" onChange={v=>patchCost(cost.id,{fixedPercent:v,variablePercent:v!==null&&cost.variablePercent===null?100-v:cost.variablePercent})}/><NumberField label={t('سهم متغیر','Variable share')} value={cost.variablePercent} unit="%" onChange={v=>patchCost(cost.id,{variablePercent:v,fixedPercent:v!==null&&cost.fixedPercent===null?100-v:cost.fixedPercent})}/></div><MetadataFields metadata={cost.metadata} language={language} onChange={metadata=>patchCost(cost.id,{metadata})}/><h5>{t('تعدیلات هزینه در هر دوره','Period cost adjustments')}</h5>{cost.adjustments.map((row,j)=><div className="fw-grid" key={j}><TextField label={t('دوره','Period')} value={row.period} onChange={v=>patchCost(cost.id,{adjustments:cost.adjustments.map((x,k)=>k===j?{...x,period:v}:x)})}/><NumberField label={t('مقدار','Quantity')} value={row.quantity} onChange={v=>patchCostAdjustment(cost.id,j,'quantity',v)}/><NumberField label={t('قیمت واحد','Unit price')} value={row.unitPrice} onChange={v=>patchCostAdjustment(cost.id,j,'unitPrice',v)}/><NumberField label={t('جمع','Total')} value={row.total} onChange={v=>patchCostAdjustment(cost.id,j,'total',v)}/><NumberField label={t('سهم ثابت','Fixed share')} value={row.fixedPercent} unit="%" onChange={v=>patchCost(cost.id,{adjustments:cost.adjustments.map((x,k)=>k===j?{...x,fixedPercent:v,variablePercent:v!==null&&x.variablePercent===null?100-v:x.variablePercent}:x)})}/><NumberField label={t('سهم متغیر','Variable share')} value={row.variablePercent} unit="%" onChange={v=>patchCost(cost.id,{adjustments:cost.adjustments.map((x,k)=>k===j?{...x,variablePercent:v,fixedPercent:v!==null&&x.fixedPercent===null?100-v:x.fixedPercent}:x)})}/></div>)}<button type="button" className="secondary-button" onClick={()=>patchCost(cost.id,{adjustments:[...cost.adjustments,{period:'',quantity:null,unitPrice:null,total:null,fixedPercent:null,variablePercent:null}]})}>{t('افزودن تعدیل دوره‌ای','Add period adjustment')}</button><button type="button" className="secondary-button" onClick={()=>onChange({...value,productionCosts:value.productionCosts.filter(x=>x.id!==cost.id)})}>{t('حذف قلم','Remove item')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={addCost}>{t('افزودن قلم هزینه','Add cost item')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۳. برنامه فروش دوره‌ای','3. Period sales programme')}</h4>
   {value.sales.map((sale,i)=><div className="fw-validation" key={i} style={{marginTop:10,padding:12}}><div className="fw-grid"><TextField label={t('شناسه محصول','Product ID')} value={sale.productId} onChange={v=>patchSales(i,{productId:v})}/><TextField label={t('واحد پایه محصول','Product base unit')} value={sale.unitOfMeasure??''} onChange={v=>patchSales(i,{unitOfMeasure:v})}/><label className="fw-field"><span>{t('روش برنامه تولید و موجودی','Production & inventory method')}</span><select value={sale.inventoryPolicy??''} onChange={e=>patchSales(i,{inventoryPolicy:(e.target.value||null) as typeof sale.inventoryPolicy})}><option value="">{t('انتخاب','Select')}</option><option value="manual">{t('ورود دستی موجودی','Manual inventory')}</option><option value="comfar-days-coverage">{t('محاسبه بر اساس روز پوشش موجودی COMFAR','COMFAR days-coverage calculation')}</option></select></label>{sale.inventoryPolicy==='comfar-days-coverage'&&<><NumberField label={t('روز پوشش کالای ساخته‌شده','Finished-goods days coverage')} value={sale.finishedGoodsDaysCoverage} onChange={v=>patchSales(i,{finishedGoodsDaysCoverage:v})}/><NumberField label={t('دوره شروع تولید','Production start period')} value={sale.productionStartPeriod} onChange={v=>patchSales(i,{productionStartPeriod:v})}/><NumberField label={t('دوره پایان تولید','Production end period')} value={sale.productionEndPeriod} onChange={v=>patchSales(i,{productionEndPeriod:v})}/></>}</div>{sale.inventoryPolicy==='comfar-days-coverage'&&<p className="fw-hint">{t('موجودی پایان دوره و مقدار تولید به‌صورت خودکار از فروش، روزهای پوشش و بازه تولید محاسبه می‌شود. دوره آخر باید موجودی باقی‌مانده را تخلیه کند.','Closing stock and production are calculated from sales, days coverage and the production interval. The final period must liquidate remaining stock.')}</p>}{sale.periods.map((period,j)=><div className="fw-grid" key={j}><TextField label={t('دوره','Period')} value={period.period} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,period:v}:p)})}/><NumberField label={t('مقدار فروش','Sales quantity')} value={period.salesQuantity} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,salesQuantity:v}:p)})}/><NumberField label={t('قیمت خالص واحد','Net unit price')} value={period.netUnitPrice} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,netUnitPrice:v}:p)})}/><NumberField label={t('مالیات فروش','Sales tax')} value={period.salesTaxPercent} unit="%" onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,salesTaxPercent:v}:p)})}/><TextField label={t('مرجع قانونی نرخ مالیات فروش','Sales-tax rate legal source')} value={period.salesTaxSourceReference??''} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,salesTaxSourceReference:v,salesTaxSourceVerified:false}:p)})}/><label className="fw-field"><span>{t('تأیید مرجع نرخ','Rate source verified')}</span><select value={period.salesTaxSourceVerified?'yes':'no'} onChange={e=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,salesTaxSourceVerified:e.target.value==='yes'}:p)})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label><NumberField label={t('درصد یارانه','Subsidy percent')} value={period.subsidyPercent} unit="%" onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,subsidyPercent:v}:p)})}/><NumberField label={t('مبلغ یارانه','Subsidy amount')} value={period.subsidyAmount} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,subsidyAmount:v}:p)})}/>{(sale.inventoryPolicy==='manual'||j===0)&&<NumberField label={t('مقدار موجودی اول دوره','Opening finished-goods quantity')} value={period.openingFinishedGoodsQuantity} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingFinishedGoodsQuantity:v}:p)})}/>}{(sale.inventoryPolicy==='manual'||j===0)&&<NumberField label={t('ارزش موجودی اول دوره','Opening finished-goods value')} value={period.openingFinishedGoodsValue} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingFinishedGoodsValue:v}:p)})}/>}{sale.inventoryPolicy==='manual'&&<NumberField label={t('موجودی پایان دوره محصول','Closing finished-goods quantity')} value={period.finishedGoodsClosingQuantity} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,finishedGoodsClosingQuantity:v}:p)})}/>}<details className="fw-validation"><summary>{t('گردش مواد و تولید/WIP (ورودی مستند)','Raw material and WIP flow (sourced inputs)')}</summary><div className="fw-grid">{j===0&&<><NumberField label={t('مقدار افتتاحیه مواد','Opening raw material quantity')} value={period.openingRawMaterialQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingRawMaterialQuantity:v}:p)})}/><NumberField label={t('ارزش افتتاحیه مواد','Opening raw material value')} value={period.openingRawMaterialValue??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingRawMaterialValue:v}:p)})}/><NumberField label={t('مقدار افتتاحیه WIP','Opening WIP quantity')} value={period.openingWipQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingWipQuantity:v}:p)})}/><NumberField label={t('ارزش مواد افتتاحیه WIP','Opening WIP material value')} value={period.openingWipMaterialValue??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingWipMaterialValue:v}:p)})}/><NumberField label={t('ارزش تبدیل افتتاحیه WIP','Opening WIP conversion value')} value={period.openingWipConversionValue??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,openingWipConversionValue:v}:p)})}/></>}<NumberField label={t('خرید مواد (مقدار)','Raw material purchases quantity')} value={period.rawMaterialPurchasesQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,rawMaterialPurchasesQuantity:v}:p)})}/><NumberField label={t('خرید مواد (ارزش)','Raw material purchases value')} value={period.rawMaterialPurchasesValue??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,rawMaterialPurchasesValue:v}:p)})}/><NumberField label={t('مصرف مواد (مقدار)','Raw material consumption quantity')} value={period.rawMaterialConsumptionQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,rawMaterialConsumptionQuantity:v}:p)})}/><NumberField label={t('ضایعات عادی مواد (مقدار)','Normal raw material waste quantity')} value={period.normalRawMaterialWasteQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,normalRawMaterialWasteQuantity:v}:p)})}/><NumberField label={t('ضایعات غیرعادی مواد (مقدار)','Abnormal raw material waste quantity')} value={period.abnormalRawMaterialWasteQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,abnormalRawMaterialWasteQuantity:v}:p)})}/><TextField label={t('مرجع سند حادثه / ضایعات غیرعادی','Abnormal-waste incident source reference')} value={period.abnormalWasteSourceReference??''} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,abnormalWasteSourceReference:v,abnormalWasteSourceVerified:false}:p)})}/><label className="fw-field"><span>{t('تأیید سند ضایعات غیرعادی','Abnormal-waste source verified')}</span><select value={period.abnormalWasteSourceVerified?'yes':'no'} onChange={e=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,abnormalWasteSourceVerified:e.target.value==='yes'}:p)})}><option value="no">{t('تأییدنشده','Unverified')}</option><option value="yes">{t('تأییدشده','Verified')}</option></select></label><NumberField label={t('واحدهای شروع‌شده','Units started')} value={period.unitsStarted??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,unitsStarted:v}:p)})}/><NumberField label={t('واحدهای تکمیل‌شده','Units completed')} value={period.unitsCompleted??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,unitsCompleted:v}:p)})}/><NumberField label={t('مقدار WIP پایان دوره','Closing WIP quantity')} value={period.closingWipQuantity??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,closingWipQuantity:v}:p)})}/><NumberField label={t('درصد تکمیل مواد','Material completion %')} value={period.materialCompletionPercent??null} unit="%" onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,materialCompletionPercent:v}:p)})}/><NumberField label={t('درصد تکمیل تبدیل','Conversion completion %')} value={period.conversionCompletionPercent??null} unit="%" onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,conversionCompletionPercent:v}:p)})}/><NumberField label={t('هزینه تبدیل دوره','Period conversion cost')} value={period.conversionCost??null} onChange={v=>patchSales(i,{periods:sale.periods.map((p,k)=>k===j?{...p,conversionCost:v}:p)})}/></div></details><details className="fw-validation"><summary>{t('شواهد صریح پل تولید و انتقال مرحله‌ای','Explicit production bridge evidence')}</summary>
<div className="fw-grid">
<TextField label={t('ارجاع سند تولید / صفحه','Production source document / page')} value={period.productionBridgeEvidence?.sourceReference??''} onChange={v=>patchProductionBridgeEvidence(i,j,{sourceReference:v,sourceVerified:false})}/>
<label className="fw-field"><span>{t('تأیید شواهد منبع','Verify source evidence')}</span><select value={period.productionBridgeEvidence?.sourceVerified?'yes':'no'} onChange={e=>patchProductionBridgeEvidence(i,j,{sourceVerified:e.target.value==='yes'})}><option value="no">{t('تأییدنشده','Unverified')}</option><option value="yes">{t('تأییدشده','Verified')}</option></select></label>
</div>
<ProductionBridgeLinkFields label={t('مواد اولیه به WIP','Raw materials to WIP')} value={period.productionBridgeEvidence?.rawMaterialsToWip??createBlankProductionBridgeEvidenceFormDraft().rawMaterialsToWip} language={language} onChange={rawMaterialsToWip=>patchProductionBridgeEvidence(i,j,{rawMaterialsToWip})}/>
<ProductionBridgeLinkFields label={t('WIP به محصول نهایی','WIP to finished goods')} value={period.productionBridgeEvidence?.wipToFinishedGoods??createBlankProductionBridgeEvidenceFormDraft().wipToFinishedGoods} language={language} onChange={wipToFinishedGoods=>patchProductionBridgeEvidence(i,j,{wipToFinishedGoods})}/>
</details></div>)}
<button type="button" className="secondary-button" onClick={()=>generateProductionBridge(i)}>{t('تولید / به‌روزرسانی خودکار انتقال‌های مستند','Generate / refresh sourced stage transfers')}</button>
{productionBridgeErrors[i]&&<p className="fw-hint" role="alert">{productionBridgeErrors[i]}</p>}
<p className="fw-hint">{t('تولید مجدد با شناسه قطعی، ردیف‌های تولیدشده قبلی را جایگزین می‌کند و انتقال‌های دستی یا نامرتبط را نگه می‌دارد. شواهد هر دوره باید جداگانه تأیید شود.','Regeneration replaces prior generated rows by deterministic ID and preserves unrelated/manual transfers. Evidence must be verified separately for every period.')}</p>
<button type="button" className="secondary-button" onClick={()=>patchSales(i,{periods:[...sale.periods,{period:'',salesQuantity:null,netUnitPrice:null,salesTaxPercent:null,subsidyPercent:null,subsidyAmount:null,openingFinishedGoodsQuantity:null,openingFinishedGoodsValue:null,finishedGoodsClosingQuantity:null,rawMaterialPurchasesQuantity:null,rawMaterialPurchasesValue:null,rawMaterialConsumptionQuantity:null,normalRawMaterialWasteQuantity:null,abnormalRawMaterialWasteQuantity:null,unitsStarted:null,unitsCompleted:null,closingWipQuantity:null,materialCompletionPercent:null,conversionCompletionPercent:null,conversionCost:null,openingRawMaterialQuantity:null,openingRawMaterialValue:null,openingWipQuantity:null,openingWipMaterialValue:null,openingWipConversionValue:null}]})}>{t('افزودن دوره فروش','Add sales period')}</button><button type="button" className="secondary-button" onClick={()=>onChange({...value,sales:value.sales.filter((_,k)=>k!==i)})}>{t('حذف محصول','Remove product')}</button></div>)}
   <button type="button" className="secondary-button" onClick={addSales}>{t('افزودن محصول فروش','Add sales product')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۴. دفتر مالیات غیرمستقیم فروش','4. Indirect sales-tax ledger')}</h4>
   <p className="fw-hint">{t('مالیات فروش به قیمت خالص اضافه می‌شود و درآمد محسوب نمی‌شود. نرخ هر محصول در برنامه فروش وارد می‌شود. مبالغ اعتبار مالیاتی خرید و پرداخت به سازمان مالیاتی باید با سند منبع ثبت شوند؛ مانده افتتاحیه نیز باید صریح باشد. مانده افتتاحیه سرمایه در گردش و اجزای جاری را بدون مالیات فروش وارد کنید؛ دفتر مالیات به‌صورت جداگانه به آن متصل می‌شود تا دوباره‌شماری رخ ندهد. پایه مشمول فعلاً قیمت خالص فروش است و یارانه را شامل نمی‌شود.','Sales tax is added to the net selling price and is not revenue. Enter each product rate in the sales programme. Purchase-tax credits and remittances require source evidence; the opening balance must be explicit. Enter opening net working capital and its components excluding sales tax; this ledger is added separately to prevent double counting. The current taxable base is net sales price and excludes subsidy income.')}</p>
   <div className="fw-grid">
    <NumberField label={t('مانده افتتاحیه مالیات فروش (+پرداختنی / −دریافتنی)','Opening sales-tax balance (+payable / −recoverable)')} value={salesTaxLedger.openingBalance} onChange={v=>patchSalesTaxLedger({openingBalance:v})}/>
   </div>
   <h5>{t('اعتبار مالیات خرید مستند','Sourced purchase-tax credits')}</h5>
   {salesTaxLedger.inputCredits.map((entry,index)=><div className="fw-grid" key={entry.id}>
    <TextField label={t('شناسه فاکتور / سند','Invoice / source ID')} value={entry.id} onChange={v=>patchSalesTaxLedger({inputCredits:salesTaxLedger.inputCredits.map((x,i)=>i===index?{...x,id:v}:x)})}/>
    <NumberField label={t('دوره','Period')} value={entry.period} onChange={v=>patchSalesTaxLedger({inputCredits:salesTaxLedger.inputCredits.map((x,i)=>i===index?{...x,period:v}:x)})}/>
    <NumberField label={t('اعتبار مالیات خرید','Recoverable input tax')} value={entry.taxAmount} onChange={v=>patchSalesTaxLedger({inputCredits:salesTaxLedger.inputCredits.map((x,i)=>i===index?{...x,taxAmount:v}:x)})}/>
    <TextField label={t('مرجع سند منبع','Source reference')} value={entry.sourceReference} onChange={v=>patchSalesTaxLedger({inputCredits:salesTaxLedger.inputCredits.map((x,i)=>i===index?{...x,sourceReference:v,sourceVerified:false}:x)})}/>
    <label className="fw-field"><span>{t('تأیید سند','Source verified')}</span><select value={entry.sourceVerified?'yes':'no'} onChange={e=>patchSalesTaxLedger({inputCredits:salesTaxLedger.inputCredits.map((x,i)=>i===index?{...x,sourceVerified:e.target.value==='yes'}:x)})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label>
    <button type="button" className="secondary-button" onClick={()=>patchSalesTaxLedger({inputCredits:salesTaxLedger.inputCredits.filter((_,i)=>i!==index)})}>{t('حذف اعتبار','Remove credit')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={()=>patchSalesTaxLedger({inputCredits:[...salesTaxLedger.inputCredits,{id:crypto.randomUUID(),period:null,taxAmount:null,sourceReference:'',sourceVerified:false}]})}>{t('افزودن اعتبار مالیات خرید','Add purchase-tax credit')}</button>
   <h5>{t('برنامه پرداخت مالیات فروش به تفکیک دوره','Sales-tax remittance by project period')}</h5>
   {projectPeriods.map((period,index)=>{const periodNo=index+1;const entry=salesTaxLedger.settlements.find(x=>x.period===periodNo);return <div className="fw-grid" key={periodNo}>
    <div className="fw-result">{t('دوره','Period')} {periodNo} · {period.startDate} – {period.endDate}</div>
    <NumberField label={t('مبلغ پرداخت / تهاتر','Cash settlement / offset')} value={entry?.amount??null} onChange={v=>patchSalesTaxLedger({settlements:[...salesTaxLedger.settlements.filter(x=>x.period!==periodNo),{period:periodNo,amount:v,sourceReference:entry?.sourceReference??'',sourceVerified:entry?.sourceVerified??false}]})}/>
    <TextField label={t('مرجع رسید پرداخت یا سند عدم پرداخت','Payment receipt / no-payment-due reference')} value={entry?.sourceReference??''} onChange={v=>patchSalesTaxLedger({settlements:[...salesTaxLedger.settlements.filter(x=>x.period!==periodNo),{period:periodNo,amount:entry?.amount??null,sourceReference:v,sourceVerified:false}]})}/>
    <label className="fw-field"><span>{t('تأیید سند پرداخت / عدم پرداخت','Settlement evidence verified')}</span><select value={entry?.sourceVerified?'yes':'no'} onChange={e=>patchSalesTaxLedger({settlements:[...salesTaxLedger.settlements.filter(x=>x.period!==periodNo),{period:periodNo,amount:entry?.amount??null,sourceReference:entry?.sourceReference??'',sourceVerified:e.target.value==='yes'}]})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label>
   </div>})}
  </div>
  <div className="fw-card">
   <h4>{t('۵. سرمایه در گردش','5. Working capital')}</h4>
   {value.workingCapital.map(item=><div className="fw-validation" key={item.id} style={{marginTop:10,padding:12}}><div className="fw-grid"><TextField label={t('شرح جزء','Component name')} value={item.name} onChange={v=>patchWorking(item.id,{name:v})}/><label className="fw-field"><span>{t('نوع جزء','Component type')}</span><select value={item.category??''} onChange={e=>patchWorking(item.id,{category:(e.target.value||null) as WorkingCapitalComponentFormDraft['category']})}><option value="">{t('انتخاب','Select')}</option>{['inventory','work-in-progress','finished-goods','receivables','cash','payables','other-current-asset','other-current-liability'].map(x=><option key={x} value={x}>{x}</option>)}</select></label><NumberField label={t('حداقل روز پوشش','Minimum days coverage')} value={item.minimumDaysCoverage} onChange={v=>patchWorking(item.id,{minimumDaysCoverage:v,turnoverCoefficient:v!==null&&v>0?360/v:null})}/><NumberField label={t('ضریب گردش','Turnover coefficient')} value={item.turnoverCoefficient} onChange={v=>patchWorking(item.id,{turnoverCoefficient:v})}/><label className="fw-field"><span>{t('مبنای ارزش‌گذاری','Valuation basis')}</span><select value={item.valuationBasis??''} onChange={e=>patchWorking(item.id,{valuationBasis:(e.target.value||null) as WorkingCapitalComponentFormDraft['valuationBasis']})}><option value="">{t('انتخاب','Select')}</option><option value="cost-of-production">Cost of production</option><option value="cost-of-sales">Cost of sales</option><option value="sales-revenue">Sales revenue</option><option value="user-defined">User defined</option></select></label></div>{item.periodBalances.map((row,j)=><div className="fw-grid" key={j}><TextField label={t('دوره','Period')} value={row.period} onChange={v=>patchWorking(item.id,{periodBalances:item.periodBalances.map((x,k)=>k===j?{...x,period:v}:x)})}/><NumberField label={t('مانده جزء','Component balance')} value={row.amount} onChange={v=>patchWorking(item.id,{periodBalances:item.periodBalances.map((x,k)=>k===j?{...x,amount:v}:x)})}/></div>)}<button type="button" className="secondary-button" onClick={()=>patchWorking(item.id,{periodBalances:[...item.periodBalances,{period:'',amount:null}]})}>{t('افزودن مانده دوره','Add period balance')}</button><button type="button" className="secondary-button" onClick={()=>onChange({...value,workingCapital:value.workingCapital.filter(x=>x.id!==item.id)})}>{t('حذف جزء','Remove component')}</button></div>)}
   <button type="button" className="secondary-button" onClick={addWorking}>{t('افزودن جزء سرمایه در گردش','Add working capital component')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۶. تسهیلات و برنامه بازپرداخت','6. Loan facilities and repayment profile')}</h4>
   {value.loans.map(loan=><div className="fw-validation" key={loan.id} style={{marginTop:10,padding:12}}><div className="fw-grid"><TextField label={t('نام تسهیلات','Facility name')} value={loan.name} onChange={v=>patchLoan(loan.id,{name:v})}/><NumberField label={t('نرخ پایه سالانه','Base annual interest rate')} value={loan.annualRatePercent} unit="%" onChange={v=>patchLoan(loan.id,{annualRatePercent:v})}/><NumberField label={t('مانده اصل ابتدای مدل','Opening principal balance')} value={loan.openingBalance} onChange={v=>patchLoan(loan.id,{openingBalance:v})}/><NumberField label={t('دوره تنفس اصل','Principal grace periods')} value={loan.gracePeriods} unit={t('دوره','periods')} onChange={v=>patchLoan(loan.id,{gracePeriods:v})}/><label className="fw-field"><span>{t('مبنای محاسبه بهره','Interest day-count convention')}</span><select value={loan.interestConvention??''} onChange={e=>patchLoan(loan.id,{interestConvention:(e.target.value||null) as LoanFacilityFormDraft['interestConvention']})}><option value="">{t('انتخاب','Select')}</option><option value="comfar-months-plus-360">COMFAR months + 360</option><option value="actual-360">Actual / 360</option><option value="actual-365">Actual / 365</option></select></label>{loan.marketOrigin==='foreign'&&<NumberField label={t('نرخ ارز ابتدای مدل','Opening FX rate to local currency')} value={loan.openingExchangeRateToLocal} onChange={v=>patchLoan(loan.id,{openingExchangeRateToLocal:v})}/>} <label className="fw-field"><span>{t('مبدأ تسهیلات','Loan currency origin')}</span><select value={loan.marketOrigin??''} onChange={e=>patchLoan(loan.id,{marketOrigin:(e.target.value||null) as LoanFacilityFormDraft['marketOrigin'],currencyCode:e.target.value==='local'?(foundation?.currencies.localCurrencyCode||null):null})}><option value="">{t('انتخاب','Select')}</option><option value="local">{t('داخلی','Local')}</option><option value="foreign">{t('ارزی','Foreign currency')}</option></select></label>{foundation?<label className="fw-field"><span>{t('ارز تسهیلات','Facility currency')}</span><select value={loan.currencyCode??''} onChange={e=>patchLoan(loan.id,{currencyCode:e.target.value||null})}><option value="">{t('انتخاب ارز','Select currency')}</option>{loan.marketOrigin==='local'&&foundation.currencies.localCurrencyCode&&<option value={foundation.currencies.localCurrencyCode}>{foundation.currencies.localCurrencyCode} — {foundation.currencies.localCurrencyName}</option>}{loan.marketOrigin==='foreign'&&foundation.currencies.foreignCurrencies.map(currency=><option key={currency.id} value={currency.code}>{currency.code} — {currency.name}</option>)}</select></label>:<TextField label={t('ارز','Currency')} value={loan.currencyCode??''} onChange={v=>patchLoan(loan.id,{currencyCode:v||null})}/>} {foundation&&loan.marketOrigin==='foreign'&&!resolveLoanFacilityCurrency(loan,foundation).valid&&<p className="fw-hint" role="alert">{t('ارز تسهیلات باید در فونداسیون پروژه تعریف شده باشد.','The foreign loan currency must be defined in the project foundation.')}</p>}<label className="fw-field"><span>{t('نوع وام','Loan type')}</span><select value={loan.loanType??''} onChange={e=>patchLoan(loan.id,{loanType:(e.target.value||null) as LoanFacilityFormDraft['loanType']})}><option value="">{t('انتخاب','Select')}</option><option value="annuity">Annuity</option><option value="constant-principal">Constant principal</option><option value="profile">Profile</option></select></label><label className="fw-field"><span>{t('فاصله اقساط','Repayment interval')}</span><select value={loan.repaymentInterval??''} onChange={e=>patchLoan(loan.id,{repaymentInterval:(e.target.value||null) as LoanFacilityFormDraft['repaymentInterval']})}><option value="">{t('انتخاب','Select')}</option>{['annual','semiannual','quarterly','monthly'].map(x=><option key={x}>{x}</option>)}</select></label><TextField label={t('تاریخ اولین قسط','First repayment date')} value={loan.firstRepaymentDate} type="date" onChange={v=>patchLoan(loan.id,{firstRepaymentDate:v})}/><NumberField label={t('تعداد اقساط','Number of repayments')} value={loan.numberOfRepayments} onChange={v=>patchLoan(loan.id,{numberOfRepayments:v})}/><NumberField label={t('درصد بهره سرمایه‌ای‌شونده','Capitalized interest share')} value={loan.capitalizedInterestPercent} unit="%" onChange={v=>patchLoan(loan.id,{capitalizedInterestPercent:v})}/><TextField label={t('پایان سرمایه‌ای‌سازی','Capitalization end date')} value={loan.capitalizeUntilDate} type="date" onChange={v=>patchLoan(loan.id,{capitalizeUntilDate:v})}/></div><h5>{t('برداشت‌ها و تغییرات نرخ','Drawdowns and rate resets')}</h5>{loan.disbursements.map((row,j)=><div className="fw-grid" key={'d'+j}><TextField label={t('تاریخ برداشت','Drawdown date')} value={row.date} type="date" onChange={v=>patchLoan(loan.id,{disbursements:loan.disbursements.map((x,k)=>k===j?{...x,date:v}:x)})}/><NumberField label={t('مبلغ برداشت','Drawdown amount')} value={row.amount} onChange={v=>patchLoan(loan.id,{disbursements:loan.disbursements.map((x,k)=>k===j?{...x,amount:v}:x)})}/></div>)}<button type="button" className="secondary-button" onClick={()=>patchLoan(loan.id,{disbursements:[...loan.disbursements,{date:'',amount:null}]})}>{t('افزودن برداشت','Add drawdown')}</button>{loan.profileMovements.map((row,j)=><div className="fw-grid" key={'p'+j}><TextField label={t('تاریخ حرکت','Movement date')} value={row.date} type="date" onChange={v=>patchLoan(loan.id,{profileMovements:loan.profileMovements.map((x,k)=>k===j?{...x,date:v}:x)})}/><NumberField label={t('مبلغ خالص حرکت (+برداشت / -بازپرداخت)','Net movement (+drawdown / -repayment)')} value={row.amount} onChange={v=>patchLoan(loan.id,{profileMovements:loan.profileMovements.map((x,k)=>k===j?{...x,amount:v}:x)})}/></div>)}<button type="button" className="secondary-button" onClick={()=>patchLoan(loan.id,{profileMovements:[...loan.profileMovements,{date:'',amount:null}]})}>{t('افزودن حرکت سفارشی','Add profile movement')}</button>{loan.interestRateChanges.map((row,j)=><div className="fw-grid" key={'r'+j}><TextField label={t('تاریخ اثر نرخ','Rate effective date')} value={row.effectiveDate} type="date" onChange={v=>patchLoan(loan.id,{interestRateChanges:loan.interestRateChanges.map((x,k)=>k===j?{...x,effectiveDate:v}:x)})}/><NumberField label={t('نرخ سالانه','Annual interest rate')} value={row.annualRatePercent} unit="%" onChange={v=>patchLoan(loan.id,{interestRateChanges:loan.interestRateChanges.map((x,k)=>k===j?{...x,annualRatePercent:v}:x)})}/></div>)}<button type="button" className="secondary-button" onClick={()=>patchLoan(loan.id,{interestRateChanges:[...loan.interestRateChanges,{effectiveDate:'',annualRatePercent:null}]})}>{t('افزودن تغییر نرخ','Add rate reset')}</button><h5>{t('برنامه قطعی اصل و بهره (ورود مستند)','Documented principal and interest override')}</h5><p className="fw-hint">{t('در این حالت، اصل، بهره نقدی، بهره سرمایه‌ای‌شده و مانده پایان دوره مستقیماً از برنامه مستند وارد می‌شوند؛ نرخ بهره از روی ارقام حدس زده نمی‌شود و نرخ پایه در محاسبه این برنامه دخالت ندارد.','In this mode, principal, cash interest, capitalized interest and closing balance are taken directly from documented period rows. No interest rate is inferred; the base rate is not used for this override.')}</p>{(loan.manualPeriodSchedule??[]).map((row,j)=><div className="fw-grid" key={'m'+j}><NumberField label={t('شماره دوره','Period index')} value={Number(row.period)} onChange={v=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).map((x,k)=>k===j?{...x,period:String(v??'')}:x)})}/><NumberField label={t('برداشت','Drawdown')} value={row.drawdown} onChange={v=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).map((x,k)=>k===j?{...x,drawdown:v??0}:x)})}/><NumberField label={t('بازپرداخت اصل','Principal repayment')} value={row.principal} onChange={v=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).map((x,k)=>k===j?{...x,principal:v??0}:x)})}/><NumberField label={t('بهره نقدی','Cash interest')} value={row.interestExpense} onChange={v=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).map((x,k)=>k===j?{...x,interestExpense:v??0}:x)})}/><NumberField label={t('بهره سرمایه‌ای‌شده','Capitalized interest')} value={row.capitalizedInterest} onChange={v=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).map((x,k)=>k===j?{...x,capitalizedInterest:v??0}:x)})}/><NumberField label={t('مانده پایان دوره','Closing balance')} value={row.closingBalance} onChange={v=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).map((x,k)=>k===j?{...x,closingBalance:v??0}:x)})}/><button type="button" className="secondary-button" onClick={()=>patchLoan(loan.id,{manualPeriodSchedule:(loan.manualPeriodSchedule??[]).filter((_,k)=>k!==j)})}>{t('حذف ردیف','Remove row')}</button></div>)}<button type="button" className="secondary-button" onClick={()=>patchLoan(loan.id,{manualPeriodSchedule:[...(loan.manualPeriodSchedule??[]),{period:String((loan.manualPeriodSchedule??[]).length+1),drawdown:0,principal:0,interestExpense:0,capitalizedInterest:0,closingBalance:0}]})}>{t('افزودن ردیف برنامه قطعی','Add documented schedule row')}</button><h5>{t('کارمزدهای تسهیلات','Facility fees')}</h5>{loan.fees.map((fee,j)=><div className="fw-grid" key={fee.id}><label className="fw-field"><span>{t('نوع کارمزد','Fee type')}</span><select value={fee.type??''} onChange={e=>patchLoan(loan.id,{fees:loan.fees.map((x,k)=>k===j?{...x,type:(e.target.value||null) as typeof fee.type}:x)})}><option value="">{t('انتخاب','Select')}</option><option value="agency">Agency</option><option value="guarantee">Guarantee</option><option value="commitment">Commitment</option><option value="other">Other</option></select></label><NumberField label={t('نرخ کارمزد','Fee rate')} value={fee.ratePercent} unit="%" onChange={v=>patchLoan(loan.id,{fees:loan.fees.map((x,k)=>k===j?{...x,ratePercent:v}:x)})}/><TextField label={t('ارز','Currency')} value={fee.currencyCode??''} onChange={v=>patchLoan(loan.id,{fees:loan.fees.map((x,k)=>k===j?{...x,currencyCode:v||null}:x)})}/></div>)}<button type="button" className="secondary-button" onClick={()=>patchLoan(loan.id,{fees:[...loan.fees,{id:crypto.randomUUID(),type:null,ratePercent:null,currencyCode:null}]})}>{t('افزودن کارمزد','Add fee')}</button><button type="button" className="secondary-button" onClick={()=>onChange({...value,loans:value.loans.filter(x=>x.id!==loan.id)})}>{t('حذف تسهیلات','Remove facility')}</button></div>)}
   <button type="button" className="secondary-button" onClick={addLoan}>{t('افزودن تسهیلات','Add facility')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۷. مالیات بر درآمد و معافیت‌ها','7. Income tax and allowances')}</h4>
   <div className="fw-grid"><label className="fw-field"><span>{t('نظام مالیاتی','Tax system')}</span><select value={value.tax.system??''} onChange={e=>onChange({...value,tax:{...value.tax,system:(e.target.value||null) as ProjectModelFinancialFormDrafts['tax']['system']}})}><option value="">{t('انتخاب','Select')}</option><option value="corporate">Corporate</option><option value="none">None</option><option value="custom">Custom</option></select></label><label className="fw-field"><span>{t('انتقال زیان','Loss carry-forward')}</span><select value={value.tax.lossCarryForward===null?'':String(value.tax.lossCarryForward)} onChange={e=>onChange({...value,tax:{...value.tax,lossCarryForward:e.target.value===''?null:e.target.value==='true'}})}><option value="">{t('انتخاب','Select')}</option><option value="true">{t('فعال','Enabled')}</option><option value="false">{t('غیرفعال','Disabled')}</option></select></label><NumberField label={t('مدت انتقال زیان','Loss carry-forward period')} value={value.tax.lossCarryForwardYears} unit={t('سال','years')} onChange={v=>onChange({...value,tax:{...value.tax,lossCarryForwardYears:v}})}/></div><h5>{t('مانده زیان سنواتی ابتدای مدل','Opening tax-loss vintages')}</h5>{value.tax.openingLossVintages.map((vintage,j)=><div className="fw-grid" key={j}><NumberField label={t('مبلغ زیان','Loss amount')} value={vintage.amount} onChange={v=>onChange({...value,tax:{...value.tax,openingLossVintages:value.tax.openingLossVintages.map((x,k)=>k===j?{...x,amount:v}:x)}})}/><NumberField label={t('شماره سال مالی ایجاد زیان نسبت به سال اول مدل','Loss origin fiscal-year index relative to model year 1')} value={vintage.originFiscalYearIndex} onChange={v=>onChange({...value,tax:{...value.tax,openingLossVintages:value.tax.openingLossVintages.map((x,k)=>k===j?{...x,originFiscalYearIndex:v}:x)}})}/><button type="button" className="secondary-button" onClick={()=>onChange({...value,tax:{...value.tax,openingLossVintages:value.tax.openingLossVintages.filter((_,k)=>k!==j)}})}>{t('حذف ردیف','Remove vintage')}</button></div>)}<button type="button" className="secondary-button" onClick={()=>onChange({...value,tax:{...value.tax,openingLossVintages:[...value.tax.openingLossVintages,{amount:null,originFiscalYearIndex:null}]}})}>{t('افزودن زیان سنواتی','Add opening tax loss')}</button>
   {value.tax.rates.map((row,j)=><div className="fw-grid" key={j}><TextField label={t('دوره مالیاتی','Tax period')} value={row.period} onChange={v=>onChange({...value,tax:{...value.tax,rates:value.tax.rates.map((x,k)=>k===j?{...x,period:v}:x)}})}/><NumberField label={t('نرخ مالیات','Tax rate')} value={row.ratePercent} unit="%" onChange={v=>onChange({...value,tax:{...value.tax,rates:value.tax.rates.map((x,k)=>k===j?{...x,ratePercent:v}:x)}})}/></div>)}<button type="button" className="secondary-button" onClick={()=>onChange({...value,tax:{...value.tax,rates:[...value.tax.rates,{period:'',ratePercent:null}]}})}>{t('افزودن نرخ دوره‌ای','Add period tax rate')}</button><h5>{t('معافیت‌ها و کسورات مالیاتی','Tax allowances and deductions')}</h5><p className="fw-hint">{t('اعتبار مالیاتی از مالیات همان دوره کسر می‌شود و مازاد استفاده‌نشده به دوره بعد منتقل نمی‌شود؛ برای انتقال اعتبار، برنامه مستقل لازم است.','Tax credits offset the same-period tax liability. Unused credits are not carried forward; that requires a separate credit-vintage schedule.')}</p>{value.tax.allowances.map((allowance,j)=><div className="fw-validation" key={allowance.id} style={{padding:10,marginTop:8}}><TextField label={t('شرح معافیت','Allowance description')} value={allowance.name} onChange={v=>onChange({...value,tax:{...value.tax,allowances:value.tax.allowances.map((x,k)=>k===j?{...x,name:v}:x)}})}/><label className="fw-field"><span>{t('نوع اثر مالیاتی','Tax treatment')}</span><select value={allowance.treatment??''} onChange={e=>onChange({...value,tax:{...value.tax,allowances:value.tax.allowances.map((x,k)=>k===j?{...x,treatment:(e.target.value||null) as typeof allowance.treatment}:x)}})}><option value="">{t('انتخاب','Select')}</option><option value="deduction">{t('کسر از درآمد مشمول مالیات','Deduction from taxable income')}</option><option value="credit">{t('اعتبار مالیاتی','Tax credit')}</option></select></label>{allowance.periodAmounts.map((row,k)=><div className="fw-grid" key={k}><TextField label={t('دوره','Period')} value={row.period} onChange={v=>onChange({...value,tax:{...value.tax,allowances:value.tax.allowances.map((x,ix)=>ix===j?{...x,periodAmounts:x.periodAmounts.map((z,zi)=>zi===k?{...z,period:v}:z)}:x)}})}/><NumberField label={t('مبلغ مجاز','Allowance amount')} value={row.amount} onChange={v=>onChange({...value,tax:{...value.tax,allowances:value.tax.allowances.map((x,ix)=>ix===j?{...x,periodAmounts:x.periodAmounts.map((z,zi)=>zi===k?{...z,amount:v}:z)}:x)}})}/></div>)}<button type="button" className="secondary-button" onClick={()=>onChange({...value,tax:{...value.tax,allowances:value.tax.allowances.map((x,k)=>k===j?{...x,periodAmounts:[...x.periodAmounts,{period:'',amount:null}]}:x)}})}>{t('افزودن مبلغ دوره‌ای','Add period amount')}</button></div>)}<button type="button" className="secondary-button" onClick={()=>onChange({...value,tax:{...value.tax,allowances:[...value.tax.allowances,{id:crypto.randomUUID(),name:'',treatment:null,periodAmounts:[]}]}})}>{t('افزودن معافیت','Add allowance')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۷. تحلیل اقتصادی و قیمت‌های سایه‌ای','7. Economic Analysis & Shadow Pricing')}</h4>
   <NumberField label={t('نرخ تنزیل اقتصادی','Economic discount rate')} value={value.economic.discountRatePercent} unit="%" onChange={v=>onChange({...value,economic:{...value.economic,discountRatePercent:v}})}/>
   <TextField label={t('مرجع سند نرخ تنزیل اقتصادی','Economic discount-rate source reference')} value={value.economic.discountRateSourceReference} onChange={v=>onChange({...value,economic:{...value.economic,discountRateSourceReference:v,discountRateSourceVerified:false}})}/>
   <label className="fw-field"><span>{t('منبع نرخ تنزیل تأیید شده','Discount-rate source verified')}</span><select value={value.economic.discountRateSourceVerified?'yes':'no'} onChange={e=>onChange({...value,economic:{...value.economic,discountRateSourceVerified:e.target.value==='yes'}})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label>
   <p className="fw-hint">{t('برای هر قلم، مبلغ مالی و ارزش اقتصادی پس از اعمال قیمت سایه‌ای را وارد کنید. مالیات و یارانه به‌عنوان انتقالات از جریان نقدی اقتصادی حذف می‌شوند.','For each item, enter the financial amount and its economic value after shadow pricing. Taxes and subsidies are removed from economic cash flow as transfer payments.')}</p>
   {value.economic.adjustments.map((item,j)=><div className="fw-validation" key={item.id} style={{padding:10,marginTop:8}}>
    <TextField label={t('شرح قلم اقتصادی','Economic item description')} value={item.name} onChange={v=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,name:v}:x)}})}/>
    <div className="fw-grid">
     <TextField label={t('دوره پروژه','Project period')} value={item.period} onChange={v=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,period:v}:x)}})}/>
     <label className="fw-field"><span>{t('اثر اقتصادی','Economic treatment')}</span><select value={item.treatment??''} onChange={e=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,treatment:(e.target.value||null) as typeof item.treatment}:x)}})}><option value="">{t('انتخاب','Select')}</option><option value="benefit">{t('منفعت / درآمد','Benefit / income')}</option><option value="cost">{t('هزینه / نهاده','Cost / input')}</option></select></label>
     <label className="fw-field"><span>{t('حوزه اثر','Effect category')}</span><select value={item.effectType??''} onChange={e=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,effectType:(e.target.value||null) as typeof item.effectType}:x)}})}><option value="">{t('انتخاب','Select')}</option><option value="general">{t('عمومی','General')}</option><option value="foreign-exchange">{t('ارز خارجی','Foreign exchange')}</option><option value="employment">{t('اشتغال','Employment')}</option></select></label>
     <NumberField label={t('مبلغ مالی','Financial amount')} value={item.financialAmount} onChange={v=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,financialAmount:v}:x)}})}/>
     <NumberField label={t('ارزش اقتصادی','Economic value')} value={item.economicAmount} onChange={v=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,economicAmount:v}:x)}})}/>
     <TextField label={t('مرجع سند قیمت سایه‌ای / تعدیل','Shadow-price / adjustment source reference')} value={item.sourceReference} onChange={v=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,sourceReference:v,sourceVerified:false}:x)}})}/>
     <label className="fw-field"><span>{t('سند قیمت سایه‌ای تأیید شده','Shadow-price source verified')}</span><select value={item.sourceVerified?'yes':'no'} onChange={e=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.map((x,k)=>k===j?{...x,sourceVerified:e.target.value==='yes'}:x)}})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label>
    </div>
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,economic:{...value.economic,adjustments:value.economic.adjustments.filter((_,k)=>k!==j)}})}>{t('حذف قلم','Remove item')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={()=>onChange({...value,economic:{...value.economic,adjustments:[...value.economic.adjustments,{id:crypto.randomUUID(),name:'',period:'',treatment:null,effectType:null,financialAmount:null,economicAmount:null,sourceReference:'',sourceVerified:false}]}})}>{t('افزودن تعدیل اقتصادی','Add economic adjustment')}</button>
   <h4>{t('دفتر ارزش افزوده مطابق COMFAR III','COMFAR III Value-Added Ledger')}</h4>
   <p className="fw-hint">{t('فروش، مالیات خروجی و مالیات عملکرد از برنامه‌های مالی پیوند می‌شوند. نهاده‌های واسطه‌ای و سرمایه‌گذاری باید با سند و تفکیک محلی/خارجی ثبت شوند. دستمزد محلی/خارجی، پرداخت‌های خروجی، مالیات‌ها و نیروی کار نیز باید با منبع مستند شوند. ارقام این بخش با CPP/CPS و سرمایه‌گذاری دوره‌ای تطبیق داده می‌شوند.','Sales, output tax and corporate tax are linked from the financial schedules. Intermediate inputs and investment must be entered with source evidence and local/foreign origin. Domestic/foreign wages, repatriated payments, taxes and labour data also require evidence. Entries are reconciled to CPP/CPS and periodic investment.')}</p>
   {projectPeriods.map((period,index)=>{
    const periodNo=index+1
    const draft=value.economic.valueAddedPeriods?.find(x=>x.period===periodNo)??createBlankValueAddedPeriodFormDraft(periodNo)
    const patch=(changes:Partial<ValueAddedPeriodFormDraft>)=>patchValueAddedPeriod(periodNo,changes)
    const patchIntermediate=(id:string,changes:Partial<ValueAddedInputFormDraft>)=>patch({intermediateInputs:draft.intermediateInputs.map(x=>x.id===id?{...x,...changes}:x)})
    const patchInvestment=(id:string,changes:Partial<ValueAddedInvestmentFormDraft>)=>patch({investmentInputs:draft.investmentInputs.map(x=>x.id===id?{...x,...changes}:x)})
    const inputFields=(item:ValueAddedInputFormDraft,kind:'intermediate'|'investment')=><div className="fw-validation" key={item.id} style={{marginTop:8,padding:8}}>
     <div className="fw-grid">
      <TextField label={t('شرح نهاده / قلم','Input / item description')} value={item.description} onChange={v=>kind==='intermediate'?patchIntermediate(item.id,{description:v}):patchInvestment(item.id,{description:v})}/>
      <NumberField label={t('مبلغ مالی','Financial amount')} value={item.amount} onChange={v=>kind==='intermediate'?patchIntermediate(item.id,{amount:v}):patchInvestment(item.id,{amount:v})}/>
      <label className="fw-field"><span>{t('منشأ بازار','Market origin')}</span><select value={item.marketOrigin??''} onChange={e=>kind==='intermediate'?patchIntermediate(item.id,{marketOrigin:(e.target.value||null) as ValueAddedInputFormDraft['marketOrigin']}):patchInvestment(item.id,{marketOrigin:(e.target.value||null) as ValueAddedInvestmentFormDraft['marketOrigin']})}><option value="">{t('انتخاب','Select')}</option><option value="local">{t('داخلی','Local')}</option><option value="foreign">{t('خارجی / وارداتی','Foreign / Imported')}</option></select></label>
      <NumberField label={t('مالیات و عوارض مندرج در مبلغ (%)','Taxes/duties included (%)')} value={item.taxesDutiesIncludedPercent} unit="%" onChange={v=>kind==='intermediate'?patchIntermediate(item.id,{taxesDutiesIncludedPercent:v}):patchInvestment(item.id,{taxesDutiesIncludedPercent:v})}/>
      {[0,1,2].map(round=><NumberField key={round} label={t('محتوای ارزش افزوده، مرحله '+(round+1)+' (%)','Value-added content, round '+(round+1)+' (%)')} value={item.valueAddedIncludedPercentages[round]} unit="%" onChange={v=>{const next=[...item.valueAddedIncludedPercentages] as [number|null,number|null,number|null];next[round]=v;kind==='intermediate'?patchIntermediate(item.id,{valueAddedIncludedPercentages:next}):patchInvestment(item.id,{valueAddedIncludedPercentages:next})}}/>)}
      <TextField label={t('مرجع سند منبع','Source reference')} value={item.sourceReference} onChange={v=>kind==='intermediate'?patchIntermediate(item.id,{sourceReference:v,sourceVerified:false}):patchInvestment(item.id,{sourceReference:v,sourceVerified:false})}/>
      <label className="fw-field"><span>{t('سند تأیید شده','Source verified')}</span><select value={item.sourceVerified?'yes':'no'} onChange={e=>kind==='intermediate'?patchIntermediate(item.id,{sourceVerified:e.target.value==='yes'}):patchInvestment(item.id,{sourceVerified:e.target.value==='yes'})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label>
      {kind==='investment'&&<label className="fw-field"><span>{t('نوع سرمایه‌گذاری','Investment type')}</span><select value={(item as ValueAddedInvestmentFormDraft).kind??''} onChange={e=>patchInvestment(item.id,{kind:(e.target.value||null) as ValueAddedInvestmentFormDraft['kind']})}><option value="">{t('انتخاب','Select')}</option><option value="fixed-investment">{t('سرمایه‌گذاری ثابت','Fixed investment')}</option><option value="pre-production-net-of-interest">{t('هزینه قبل از تولید خالص از بهره','Pre-production cost net of interest')}</option><option value="inventory-increase">{t('افزایش / کاهش موجودی','Inventory increase / decrease')}</option></select></label>}
      <button type="button" className="secondary-button" onClick={()=>kind==='intermediate'?patch({intermediateInputs:draft.intermediateInputs.filter(x=>x.id!==item.id)}):patch({investmentInputs:draft.investmentInputs.filter(x=>x.id!==item.id)})}>{t('حذف قلم','Remove item')}</button>
     </div>
    </div>
    return <div className="fw-validation" key={periodNo} style={{marginTop:12,padding:12}}>
     <h5>{t('دوره ','Period ')}{periodNo} · {period.startDate} – {period.endDate}</h5>
     <div className="fw-grid">
      <NumberField label={t('سایر درآمدها','Other income')} value={draft.otherIncome} onChange={v=>patch({otherIncome:v})}/>
      <NumberField label={t('سایر ارزش افزوده / مازاد عملیاتی','Other value added / operating surplus')} value={draft.otherValueAdded} onChange={v=>patch({otherValueAdded:v})}/>
      <NumberField label={t('دستمزد نیروی کار داخلی','Domestic wages')} value={draft.domesticWages} onChange={v=>patch({domesticWages:v})}/>
      <NumberField label={t('دستمزد پرداختی به خارج','Repatriated wages')} value={draft.repatriatedWages} onChange={v=>patch({repatriatedWages:v})}/>
      <NumberField label={t('سود سهام / سود پرداختی به خارج','Repatriated profit / dividends')} value={draft.repatriatedProfitDividends} onChange={v=>patch({repatriatedProfitDividends:v})}/>
      <NumberField label={t('بهره پرداختی به خارج','Repatriated interest')} value={draft.repatriatedInterest} onChange={v=>patch({repatriatedInterest:v})}/>
      <NumberField label={t('سایر پرداخت‌های خروجی','Other repatriated payments')} value={draft.repatriatedOther} onChange={v=>patch({repatriatedOther:v})}/>
      <NumberField label={t('سود سهام و بهره داخلی','Domestic dividends and interest')} value={draft.domesticDividendsAndInterest} onChange={v=>patch({domesticDividendsAndInterest:v})}/>
      <NumberField label={t('یارانه نهاده‌ها','Input subsidies')} value={draft.subsidiesOnInput} onChange={v=>patch({subsidiesOnInput:v})}/>
      <NumberField label={t('یارانه سرمایه‌گذاری','Investment subsidies')} value={draft.subsidiesOnInvestment} onChange={v=>patch({subsidiesOnInvestment:v})}/>
      <NumberField label={t('نیروی کار ماهر (نفر-دوره)','Skilled labour (person-periods)')} value={draft.skilledDomesticLabour} onChange={v=>patch({skilledDomesticLabour:v})}/>
      <NumberField label={t('کل نیروی کار داخلی (نفر-دوره)','Total domestic labour (person-periods)')} value={draft.totalDomesticLabour} onChange={v=>patch({totalDomesticLabour:v})}/>
      <NumberField label={t('خروج ارز خارجی (ارز مبنا)','Foreign-exchange outflow (numeraire)')} value={draft.foreignExchangeOutflow} onChange={v=>patch({foreignExchangeOutflow:v})}/>
      <TextField label={t('مرجع اسناد دستمزد و پرداخت‌ها','Wage and payment source reference')} value={draft.sourceReference} onChange={v=>patch({sourceReference:v,sourceVerified:false})}/>
      <label className="fw-field"><span>{t('تأیید اسناد دوره','Period sources verified')}</span><select value={draft.sourceVerified?'yes':'no'} onChange={e=>patch({sourceVerified:e.target.value==='yes'})}><option value="no">{t('خیر','No')}</option><option value="yes">{t('بله','Yes')}</option></select></label>
     </div>
     <h5>{t('مصرف واسطه‌ای؛ بدون دستمزد','Intermediate consumption; excluding wages')}</h5>
     {draft.intermediateInputs.map(item=>inputFields(item,'intermediate'))}
     <button type="button" className="secondary-button" onClick={()=>patch({intermediateInputs:[...draft.intermediateInputs,createBlankValueAddedInputFormDraft(crypto.randomUUID())]})}>{t('افزودن نهاده واسطه‌ای','Add intermediate input')}</button>
     <h5>{t('سرمایه‌گذاری و تغییر موجودی','Investment and inventory change')}</h5>
     {draft.investmentInputs.map(item=>inputFields(item,'investment'))}
     <button type="button" className="secondary-button" onClick={()=>patch({investmentInputs:[...draft.investmentInputs,createBlankValueAddedInvestmentFormDraft(crypto.randomUUID())]})}>{t('افزودن قلم سرمایه‌گذاری','Add investment item')}</button>
    </div>
   })}
  </div>

  <div className="fw-card">
   <h4>{t('۸. ساختار مراکز هزینه','8. Cost centre structure')}</h4>
   <p className="fw-hint">{t('هر مرکز هزینه را یک‌بار تعریف کنید و سپس اقلام دفتر CPP/CPS را به آن متصل کنید. شناسه‌ها باید یکتا و پایدار باشند.','Define each cost centre once, then assign CPP/CPS trace items to it. IDs must be unique and stable.')}</p>
   {costCentres.map(centre=><div className="fw-validation" key={centre.id} style={{marginTop:10,padding:12}}>
    <div className="fw-grid">
     <TextField label={t('شناسه مرکز هزینه','Cost centre ID')} value={centre.id} onChange={v=>patchCostCentre(centre.id,{id:v})}/>
     <TextField label={t('نام مرکز هزینه','Cost centre name')} value={centre.name} onChange={v=>patchCostCentre(centre.id,{name:v})}/>
     <label className="fw-field"><span>{t('نوع مرکز','Centre type')}</span><select value={centre.type??''} onChange={e=>patchCostCentre(centre.id,{type:(e.target.value||null) as CostCentreFormDraft['type']})}><option value="">{t('انتخاب','Select')}</option><option value="production">{t('تولیدی','Production')}</option><option value="service">{t('خدماتی','Service')}</option><option value="administration">{t('اداری','Administration')}</option><option value="sales">{t('فروش','Sales')}</option><option value="other">{t('سایر','Other')}</option></select></label>
     <TextField label={t('شرح مرکز','Centre description')} value={centre.description} onChange={v=>patchCostCentre(centre.id,{description:v})}/>
     <label className="fw-field"><span>{t('مبنای تخصیص مرکز','Centre allocation basis')}</span><select value={centre.allocationBasis??''} onChange={e=>patchCostCentre(centre.id,{allocationBasis:(e.target.value||null) as CostCentreFormDraft['allocationBasis'],driverRows:e.target.value==='manual'?centre.driverRows:[]})}><option value="">{t('بدون مبنای تخصیص','No allocation basis')}</option><option value="production-quantity">{t('مقدار تولید','Production quantity')}</option><option value="sales-revenue">{t('درآمد فروش','Sales revenue')}</option><option value="manual">{t('محرک دستی محصول/دوره','Manual product-period driver')}</option></select></label>
    </div>
    {centre.allocationBasis==='manual'&&<div className="fw-validation" style={{marginTop:8,padding:8}}>
     <div className="fw-grid"><TextField label={t('نام محرک','Driver name')} value={centre.manualDriverName} onChange={v=>patchCostCentre(centre.id,{manualDriverName:v})}/><TextField label={t('واحد محرک','Driver unit')} value={centre.manualDriverUnit} onChange={v=>patchCostCentre(centre.id,{manualDriverUnit:v})}/></div>
     <b>{t('مقادیر محرک تخصیص','Allocation driver values')}</b>
     {centre.driverRows.map((driver,index)=><div className="fw-grid" key={index}>
      <NumberField label={t('شماره دوره','Period number')} value={driver.period} onChange={v=>patchCostCentre(centre.id,{driverRows:centre.driverRows.map((x,i)=>i===index?{...x,period:v??1}:x)})}/>
      <TextField label={t('شناسه محصول','Product ID')} value={driver.productId} onChange={v=>patchCostCentre(centre.id,{driverRows:centre.driverRows.map((x,i)=>i===index?{...x,productId:v}:x)})}/>
      <NumberField label={t('مقدار محرک','Driver amount')} value={driver.amount} onChange={v=>patchCostCentre(centre.id,{driverRows:centre.driverRows.map((x,i)=>i===index?{...x,amount:v}:x)})}/>
      <button type="button" className="secondary-button" onClick={()=>patchCostCentre(centre.id,{driverRows:centre.driverRows.filter((_,i)=>i!==index)})}>{t('حذف محرک','Remove driver')}</button>
     </div>)}
     <button type="button" className="secondary-button" onClick={()=>patchCostCentre(centre.id,{driverRows:[...centre.driverRows,{period:1,productId:'',amount:null}]})}>{t('افزودن محرک دوره/محصول','Add period/product driver')}</button>
    </div>}
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,costCentres:costCentres.filter(x=>x.id!==centre.id)})}>{t('حذف مرکز هزینه','Remove cost centre')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={addCostCentre}>{t('افزودن مرکز هزینه','Add cost centre')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('۹. دفتر ردیابی تفصیلی هزینه‌های CPP/CPS','9. Detailed CPP/CPS Cost Traceability Ledger')}</h4>
   <p className="fw-hint">{t('برای هر قلم مواد، نیروی انسانی، انرژی، تعمیرات و سربار، مبنا، رفتار هزینه، پوشش در بهای پایه، روش تخصیص و سند منبع را ثبت کنید. فقط بخش مستندِ خارج از پوشش به CPP افزوده می‌شود. تا وقتی منبع معتبر وارد نشده، مبالغ باید خالی بمانند؛ اقلام CRC200 فاقد مدرک به‌صورت تأییدنشده نگهداری می‌شوند.','For each material, labour, energy, maintenance and overhead item, record its basis, cost behaviour, base-cost coverage, allocation method and source evidence. Only the evidenced uncovered portion is added to CPP. Amounts stay blank until a valid source is supplied; unsupported CRC200 entries remain unverified.')}</p>
    <p className="fw-hint">{t('مبلغ مواد در این دفتر باید هزینه مواد مصرف‌شده در تولید باشد؛ خرید و ورود به انبار مواد اولیه را در فرم گردش موجودی مواد ثبت کنید تا دوباره‌شماری رخ ندهد.','Material amounts in this ledger must represent materials consumed in production. Record purchases and receipts in the raw-material inventory movement form to prevent double counting.')}</p>
   {traceItems.map(item=><div className="fw-validation" key={item.id} style={{marginTop:10,padding:12}}>
    <div className="fw-grid">
     <TextField label={t('شرح قلم هزینه','Cost item')} value={item.label} onChange={v=>patchTrace(item.id,{label:v})}/><label className="fw-field"><span>{t('مرکز هزینه','Cost centre')}</span><select value={item.costCentreId??''} onChange={e=>patchTrace(item.id,{costCentreId:e.target.value||null})}><option value="">{t('انتخاب مرکز هزینه','Select cost centre')}</option>{costCentres.map(centre=><option key={centre.id} value={centre.id}>{centre.name||centre.id}</option>)}{item.costCentreId&&!costCentres.some(centre=>centre.id===item.costCentreId)&&<option value={item.costCentreId}>{item.costCentreId} — {t('تعریف‌نشده','Undefined')}</option>}</select></label>
     <label className="fw-field"><span>{t('گروه هزینه','Cost category')}</span><select value={item.category} onChange={e=>patchTrace(item.id,{category:e.target.value as CppCpsTraceItem['category']})}>{[['materials','مواد'],['labour','نیروی انسانی'],['energy','انرژی'],['maintenance','تعمیرات'],['overhead','سربار']].map(([v,l])=><option key={v} value={v}>{t(l,v==='materials'?'Materials':v==='labour'?'Labour':v==='energy'?'Energy':v==='maintenance'?'Maintenance':'Overhead')}</option>)}</select></label>
     <label className="fw-field"><span>{t('مبنای محاسبه','Cost basis')}</span><select value={item.basis??''} onChange={e=>patchTrace(item.id,{basis:(e.target.value||null) as CppCpsTraceItem['basis']})}><option value="">{t('انتخاب','Select')}</option><option value="per-unit-output">{t('به‌ازای واحد محصول','Per unit output')}</option><option value="nominal-capacity">{t('بر مبنای ظرفیت اسمی','Nominal capacity')}</option><option value="period-total">{t('جمع هر دوره','Period total')}</option><option value="period-adjustments">{t('تعدیلات دوره‌ای','Period adjustments')}</option></select></label>
     <label className="fw-field"><span>{t('رفتار هزینه','Cost behaviour')}</span><select value={item.behaviour??''} onChange={e=>patchTrace(item.id,{behaviour:(e.target.value||null) as CppCpsTraceItem['behaviour'],fixedPercent:e.target.value==='fixed'?100:e.target.value==='variable'?0:item.fixedPercent,variablePercent:e.target.value==='fixed'?0:e.target.value==='variable'?100:item.variablePercent})}><option value="">{t('انتخاب','Select')}</option><option value="fixed">{t('ثابت','Fixed')}</option><option value="variable">{t('متغیر','Variable')}</option><option value="mixed">{t('مختلط','Mixed')}</option></select></label>
     <NumberField label={t('سهم ثابت','Fixed share')} value={item.fixedPercent} unit="%" onChange={v=>patchTrace(item.id,{fixedPercent:v,behaviour:'mixed'})}/>
     <NumberField label={t('سهم متغیر','Variable share')} value={item.variablePercent} unit="%" onChange={v=>patchTrace(item.id,{variablePercent:v,behaviour:'mixed'})}/>
     <label className="fw-field"><span>{t('روش تخصیص','Allocation method')}</span><select value={item.allocationMethod} onChange={e=>patchTrace(item.id,{allocationMethod:e.target.value as CppCpsTraceItem['allocationMethod'],productId:e.target.value==='direct-product'?item.productId:null})}><option value="not-allocated">{t('بدون تخصیص','Not allocated')}</option><option value="direct-product">{t('مستقیم به محصول','Direct product')}</option><option value="production-quantity">{t('بر اساس مقدار تولید','Production quantity')}</option><option value="revenue">{t('بر اساس درآمد فروش','Sales revenue')}</option><option value="cost-centre-driver">{t('بر اساس محرک مرکز هزینه','Cost-centre driver')}</option></select></label>
     {item.allocationMethod==='direct-product'&&<TextField label={t('شناسه محصول مقصد','Target product ID')} value={item.productId??''} onChange={v=>patchTrace(item.id,{productId:v||null})}/>}
     <label className="fw-field"><span>{t('پوشش در بهای پایه','Base-cost coverage')}</span><select disabled={item.source.status!=='verified'} value={item.baseCostCoverage} onChange={e=>patchTrace(item.id,{baseCostCoverage:e.target.value as CppCpsTraceItem['baseCostCoverage']})}><option value="unverified">{t('نامشخص / تأییدنشده','Unverified')}</option><option value="fully-included">{t('کاملاً منظور شده','Fully included')}</option><option value="partially-included">{t('بخشی منظور شده','Partially included')}</option><option value="excluded">{t('منظور نشده','Excluded')}</option></select></label>
    </div>
    <div className="fw-grid">
     <TextField label={t('شناسه سند منبع','Source reference')} value={item.source.reference} onChange={v=>patchTraceSource(item.id,{reference:v})}/>
     <TextField label={t('شرح و محل داده منبع','Source description / location')} value={item.source.description} onChange={v=>patchTraceSource(item.id,{description:v})}/>
     <label className="fw-field"><span>{t('اعتبار منبع','Source reliability')}</span><select value={item.source.reliability} onChange={e=>patchTraceSource(item.id,{reliability:e.target.value as CppCpsTraceItem['source']['reliability']})}><option value="unverified">{t('فاقد مدرک / تأییدنشده','Unverified / no evidence')}</option><option value="primary-document">{t('سند اولیه','Primary document')}</option><option value="audited-report">{t('گزارش حسابرسی‌شده','Audited report')}</option><option value="management-record">{t('دفتر/گزارش مدیریت','Management record')}</option><option value="secondary-source">{t('منبع ثانویه','Secondary source')}</option></select></label>
     <div className="fw-result">{t('وضعیت منبع','Source status')}: <b>{item.source.status==='verified'?t('مستند','Verified'):t('تأییدنشده','Unverified')}</b></div>
    </div>
    {item.source.status==='verified'&&item.baseCostCoverage!=='unverified'?<div className="fw-card">
     <h5>{t('مبالغ دوره‌ای و پوشش هزینه پایه','Period amounts and base-cost coverage')}</h5>
     {projectPeriods.map((period,index)=><div className="fw-grid" key={index}>
      <div className="fw-result">{t('دوره','Period')} {index+1} · {period.startDate} – {period.endDate}</div>
      <NumberField label={t('هزینه ناخالص مستند','Gross sourced cost')} value={item.periodAmounts[index]??null} onChange={v=>patchTrace(item.id,{periodAmounts:item.periodAmounts.map((x,i)=>i===index?v:x)})}/>
      {item.baseCostCoverage==='partially-included'&&<NumberField label={t('مبلغ منظورشده در بهای پایه','Amount already in base cost')} value={item.baseCoveredAmounts[index]??null} onChange={v=>patchTrace(item.id,{baseCoveredAmounts:item.baseCoveredAmounts.map((x,i)=>i===index?v:x)})}/>}
     </div>)}
    </div>:<p className="fw-hint" role="status">{t('برای ورود مبلغ، شناسه و شرح منبع و سطح اعتبار را تکمیل کنید و پوشش در بهای پایه را مشخص کنید. در غیر این صورت ارقام خالی و وضعیت تأییدنشده باقی می‌ماند.','Enter a source reference, description and reliability level, then select base-cost coverage before entering amounts. Otherwise amounts remain blank and unverified.')}</p>}
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,cppCpsTraceItems:traceItems.filter(x=>x.id!==item.id)})}>{t('حذف قلم ردیابی','Remove trace item')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={addTrace}>{t('افزودن قلم به دفتر CPP/CPS','Add CPP/CPS trace item')}</button>
  </div>
  {errors.length>0&&<div className="fw-validation" role="alert"><b>{t('موارد نیازمند اصلاح','Validation issues')}</b><ul>{errors.map((error,i)=><li key={i}>{error}</li>)}</ul></div>}
  <div className="fw-card">
   <h4>{t('دفتر ضایعات تولید','Production waste ledger')}</h4>
   <p className="fw-hint">{t('ضایعات عادی در بهای تولید جذب می‌شود؛ ضایعات غیرعادی باید جداگانه به‌عنوان هزینه دوره گزارش شود.','Normal waste is absorbed into production cost; abnormal waste is separately expensed.')}</p>
   {(value.wasteLedgerEntries??[]).map((entry,index)=><div className="fw-grid" key={entry.id}>
    <TextField label={t('شناسه محصول','Product ID')} value={entry.productId} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,productId:v}:x)})}/>
    <TextField label={t('مرکز هزینه','Cost centre')} value={entry.costCentreId} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,costCentreId:v}:x)})}/>
    <NumberField label={t('دوره','Period')} value={entry.period} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,period:v??0}:x)})}/>
    <label className="fw-field"><span>{t('طبقه ضایعات','Waste classification')}</span><select value={entry.classification} onChange={e=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,classification:e.target.value as typeof x.classification}:x)})}><option value="normal">{t('عادی','Normal')}</option><option value="abnormal">{t('غیرعادی','Abnormal')}</option></select></label>
    <NumberField label={t('مقدار','Quantity')} value={entry.quantity} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,quantity:v??0}:x)})}/>
    <NumberField label={t('بهای واحد','Unit cost')} value={entry.unitCost} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,unitCost:v??0,amount:(v??0)*x.quantity}:x)})}/>
    <NumberField label={t('ارزش ضایعات','Waste value')} value={entry.amount} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,amount:v??0}:x)})}/>
    <TextField label={t('مرجع سند / صفحه ضایعات','Waste source document / page')} value={entry.sourceReference??''} onChange={v=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,sourceReference:v,sourceVerified:false}:x)})}/>
    <label className="fw-field"><span>{t('تأیید سند منبع','Source document verified')}</span><select value={entry.sourceVerified?'yes':'no'} onChange={e=>onChange({...value,wasteLedgerEntries:(value.wasteLedgerEntries??[]).map((x,i)=>i===index?{...x,sourceVerified:e.target.value==='yes'}:x)})}><option value="no">{t('تأییدنشده','Unverified')}</option><option value="yes">{t('تأییدشده','Verified')}</option></select></label>
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,wasteLedgerEntries:value.wasteLedgerEntries.filter(x=>x.id!==entry.id)})}>{t('حذف','Remove')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={()=>onChange({...value,wasteLedgerEntries:[...(value.wasteLedgerEntries??[]),{id:crypto.randomUUID(),period:1,productId:'',costCentreId:'',classification:'normal',quantity:0,unitCost:0,amount:0,sourceReference:'',sourceVerified:false}]})}>{t('افزودن ضایعات','Add waste entry')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('دفتر انتقال بین محصولات و مراکز تولید','Inter-product and cost-centre transfer ledger')}</h4>
   {(value.productionTransfers??[]).map((entry,index)=><div className="fw-grid" key={entry.id}>
    <TextField label={t('محصول مبدأ','Source product')} value={entry.sourceProductId} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,sourceProductId:v}:x)})}/>
    <TextField label={t('مرکز هزینه مبدأ','Source cost centre')} value={entry.sourceCostCentreId} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,sourceCostCentreId:v}:x)})}/>
    <TextField label={t('محصول مقصد','Destination product')} value={entry.destinationProductId} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,destinationProductId:v}:x)})}/>
    <TextField label={t('مرکز هزینه مقصد','Destination cost centre')} value={entry.destinationCostCentreId} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,destinationCostCentreId:v}:x)})}/>
    <NumberField label={t('دوره','Period')} value={entry.period} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,period:v??0}:x)})}/>
    <NumberField label={t('مقدار انتقال در واحد مبدأ','Transferred quantity in source unit')} value={entry.quantity} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,quantity:v??0}:x)})}/>
    <TextField label={t('واحد مبدأ','Source unit')} value={entry.sourceUnit} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,sourceUnit:v}:x)})}/>
    <TextField label={t('واحد مقصد','Destination unit')} value={entry.destinationUnit} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,destinationUnit:v}:x)})}/>
    <NumberField label={t('ضریب تبدیل (مقدار مقصد به ازای یک واحد مبدأ)','Conversion factor (destination units per source unit)')} value={entry.conversionFactor} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,conversionFactor:v??0}:x)})}/>
    <NumberField label={t('ارزش انتقال','Transfer value')} value={entry.costAmount} onChange={v=>onChange({...value,productionTransfers:(value.productionTransfers??[]).map((x,i)=>i===index?{...x,costAmount:v??0}:x)})}/>
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,productionTransfers:value.productionTransfers.filter(x=>x.id!==entry.id)})}>{t('حذف','Remove')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={()=>onChange({...value,productionTransfers:[...(value.productionTransfers??[]),{id:crypto.randomUUID(),period:1,sourceProductId:'',destinationProductId:'',sourceCostCentreId:'',destinationCostCentreId:'',quantity:0,sourceUnit:'',destinationUnit:'',conversionFactor:0,costAmount:0}]})}>{t('افزودن انتقال','Add transfer')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('دفتر ارقام مرجع برای تطبیق تاریخی موجودی و CPP/CPS','Source evidence register for historical inventory and CPP/CPS reconciliation')}</h4>
   <p className="fw-hint">{t('برای هر دوره، ارقام را عیناً از خروجی مرجع وارد کنید و نام سند، جدول، صفحه و ارز را ثبت کنید. خانه‌های بدون شاهد را خالی بگذارید؛ صفر به‌معنای داده ناموجود نیست.','Enter figures exactly as published for each period and record document, schedule, page and currency. Leave unsupported fields blank; zero is not a substitute for missing evidence.')}</p>
   {(value.inventoryReferenceBenchmarks??[]).map((entry,index)=><div className="fw-grid" key={entry.id}>
    <NumberField label={t('دوره پروژه','Project period')} value={entry.period} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,period:v??0}:x)})}/>
    <TextField label={t('نام سند مرجع','Reference document')} value={entry.sourceDocument} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,sourceDocument:v}:x)})}/>
    <TextField label={t('نام جدول / گزارش','Schedule / report name')} value={entry.schedule} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,schedule:v}:x)})}/>
    <TextField label={t('شماره صفحه','Page number')} value={entry.page} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,page:v}:x)})}/>
    <TextField label={t('کد ارز گزارش (مثلاً IRR)','Report currency code (e.g. IRR)')} value={entry.currency} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,currency:v}:x)})}/>
    <NumberField label={t('ضریب تبدیل واحد مبلغ مرجع به واحد مدل','Reference amount scale to model units')} value={entry.amountScaleToModel} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,amountScaleToModel:v}:x)})}/>
    <NumberField label={t('موجودی مواد اولیه','Raw materials')} value={entry.rawMaterials} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,rawMaterials:v}:x)})}/>
    <NumberField label={t('کالای در جریان ساخت','Work in progress')} value={entry.workInProgress} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,workInProgress:v}:x)})}/>
    <NumberField label={t('محصول نهایی','Finished goods')} value={entry.finishedGoods} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,finishedGoods:v}:x)})}/>
    <NumberField label={t('جمع موجودی','Total inventory')} value={entry.totalInventory} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,totalInventory:v}:x)})}/>
    <NumberField label={t('بهای تولید (CPP)','Cost of products produced (CPP)')} value={entry.cpp} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,cpp:v}:x)})}/>
    <NumberField label={t('بهای محصول فروخته‌شده (CPS)','Cost of products sold (CPS)')} value={entry.cps} onChange={v=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.map((x,i)=>i===index?{...x,cps:v}:x)})}/>
    <button type="button" className="secondary-button" onClick={()=>onChange({...value,inventoryReferenceBenchmarks:value.inventoryReferenceBenchmarks.filter(x=>x.id!==entry.id)})}>{t('حذف دوره مرجع','Remove benchmark')}</button>
   </div>)}
   <button type="button" className="secondary-button" onClick={()=>onChange({...value,inventoryReferenceBenchmarks:[...(value.inventoryReferenceBenchmarks??[]),{id:crypto.randomUUID(),period:1,sourceDocument:'',schedule:'',page:'',currency:'',amountScaleToModel:null,rawMaterials:null,workInProgress:null,finishedGoods:null,totalInventory:null,cpp:null,cps:null}]})}>{t('افزودن دوره مرجع','Add reference period')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('دفتر تفصیلی موجودی مراکز هزینه','Cost-centre inventory movement register')}</h4>
   <p className="fw-hint">{t('برای هر مرحله موجودی، محصول، مرکز هزینه و دوره یک ردیف مستقل ثبت کنید. انتقال داخلی ورودی و خروجی را جداگانه ثبت کنید؛ جمع مقدار و ارزش انتقال‌های ورودی و خروجی هر مرحله در هر دوره باید برابر باشد. تمام مقادیر ابتدا خالی هستند؛ ثبت ردیف به‌تنهایی هیچ عددی را صفر یا تأییدشده نمی‌کند. تا زمان اتصال این دفتر به موتور سه‌مرحله‌ای موجودی، ورود داده در این بخش مانع تأیید گزارش مالی خواهد بود.','Enter a separate row for each inventory stage, product, cost centre and period. Record internal transfer-in and transfer-out separately; their quantities and values must balance within each stage and period. All amounts start blank; adding a row never implies zero or verified data. Until this register is posted into the three-stage inventory engine, entered rows block financial-report approval.')}</p>
   {(value.costCentreInventoryMovements??[]).map((entry,index)=>{
    const patch=(changes:Partial<typeof entry>)=>onChange({...value,costCentreInventoryMovements:(value.costCentreInventoryMovements??[]).map((row,i)=>i===index?{...row,...changes}:row)})
    return <div className="fw-grid" key={entry.id}>
     <label className="fw-field"><span>{t('مرحله موجودی','Inventory stage')}</span><select value={entry.inventoryStage??''} onChange={e=>patch({inventoryStage:(e.target.value||null) as typeof entry.inventoryStage})}><option value="">{t('انتخاب مرحله','Select stage')}</option><option value="raw-materials">{t('مواد اولیه','Raw materials')}</option><option value="work-in-progress">{t('کالای در جریان ساخت','Work in progress')}</option><option value="finished-goods">{t('محصول نهایی','Finished goods')}</option></select></label>
     <TextField label={t('شناسه محصول','Product ID')} value={entry.productId} onChange={v=>patch({productId:v})}/>
     <TextField label={t('مرکز هزینه','Cost centre')} value={entry.costCentreId} onChange={v=>patch({costCentreId:v})}/>
     <NumberField label={t('دوره','Period')} value={entry.period} onChange={v=>patch({period:v})}/>
     <NumberField label={t('مقدار اول دوره','Opening quantity')} value={entry.openingQuantity} onChange={v=>patch({openingQuantity:v})}/>
     <NumberField label={t('ارزش اول دوره','Opening value')} value={entry.openingValue} onChange={v=>patch({openingValue:v})}/>
     <NumberField label={t('مقدار ورودی/رسید','Receipts quantity')} value={entry.receiptsQuantity} onChange={v=>patch({receiptsQuantity:v})}/>
     <NumberField label={t('ارزش ورودی/رسید','Receipts value')} value={entry.receiptsValue} onChange={v=>patch({receiptsValue:v})}/>
     <NumberField label={t('مقدار انتقال داخلی ورودی','Internal transfer-in quantity')} value={entry.transfersInQuantity} onChange={v=>patch({transfersInQuantity:v})}/>
     <NumberField label={t('ارزش انتقال داخلی ورودی','Internal transfer-in value')} value={entry.transfersInValue} onChange={v=>patch({transfersInValue:v})}/>
     <NumberField label={t('مقدار انتقال داخلی خروجی','Internal transfer-out quantity')} value={entry.transfersOutQuantity} onChange={v=>patch({transfersOutQuantity:v})}/>
     <NumberField label={t('ارزش انتقال داخلی خروجی','Internal transfer-out value')} value={entry.transfersOutValue} onChange={v=>patch({transfersOutValue:v})}/>
     <NumberField label={t('مقدار تولید/تکمیل ورودی','Production quantity')} value={entry.productionQuantity} onChange={v=>patch({productionQuantity:v})}/>
     <NumberField label={t('ارزش تولید/تکمیل ورودی','Production value')} value={entry.productionValue} onChange={v=>patch({productionValue:v})}/>
     <NumberField label={t('مقدار مصرف/خروج','Consumption quantity')} value={entry.consumptionQuantity} onChange={v=>patch({consumptionQuantity:v})}/>
     <NumberField label={t('ارزش مصرف/خروج','Consumption value')} value={entry.consumptionValue} onChange={v=>patch({consumptionValue:v})}/>
     <NumberField label={t('مقدار فروش محصول نهایی','Finished-goods sales quantity')} value={entry.salesQuantity} onChange={v=>patch({salesQuantity:v})}/>
     <NumberField label={t('بهای تمام‌شده کالای فروش‌رفته','Cost of goods sold')} value={entry.salesCostValue} onChange={v=>patch({salesCostValue:v})}/>
     <NumberField label={t('مقدار ضایعات','Waste quantity')} value={entry.wasteQuantity} onChange={v=>patch({wasteQuantity:v})}/>
     <NumberField label={t('ارزش ضایعات','Waste value')} value={entry.wasteValue} onChange={v=>patch({wasteValue:v})}/>
     <NumberField label={t('مقدار پایان دوره','Closing quantity')} value={entry.closingQuantity} onChange={v=>patch({closingQuantity:v})}/>
     <NumberField label={t('ارزش پایان دوره','Closing value')} value={entry.closingValue} onChange={v=>patch({closingValue:v})}/>
     <TextField label={t('ارجاع منبع / سند / صفحه','Source reference / document / page')} value={entry.sourceReference} onChange={v=>patch({sourceReference:v})}/>
     <label className="fw-field"><span>{t('وضعیت منبع','Source status')}</span><select value={entry.sourceVerified?'verified':'unverified'} onChange={e=>patch({sourceVerified:e.target.value==='verified'})}><option value="unverified">{t('تأییدنشده','Unverified')}</option><option value="verified">{t('تأییدشده','Verified')}</option></select></label>
     <button type="button" className="secondary-button" onClick={()=>onChange({...value,costCentreInventoryMovements:(value.costCentreInventoryMovements??[]).filter(row=>row.id!==entry.id)})}>{t('حذف ردیف','Remove row')}</button>
    </div>
   })}
   <button type="button" className="secondary-button" onClick={()=>onChange({...value,costCentreInventoryMovements:[...(value.costCentreInventoryMovements??[]),createBlankCostCentreInventoryMovementFormDraft(crypto.randomUUID())]})}>{t('افزودن ردیف موجودی مرکز هزینه','Add cost-centre inventory row')}</button>
  </div>
  <div className="fw-card">
   <h4>{t('دفتر انتقال بین مراحل موجودی','Inter-stage inventory transfer register')}</h4>
   <p className="fw-hint">{t('انتقال مواد اولیه به WIP و WIP به محصول نهایی را با سند مستقل ثبت کنید. ارزش انتقال از مرحله مبدأ به مقصد منتقل می‌شود و نباید دوباره به موجودی کل اضافه شود؛ هزینه تبدیل افزوده‌شده در مرحله مقصد جداگانه در دفتر تولید ثبت می‌شود.','Record raw-material-to-WIP and WIP-to-finished-goods movements as explicit transfers. Transfer value moves from source to destination and must not be added again to total inventory; conversion costs added at the destination remain separate production costs.')}</p>
   {(value.inventoryStageTransfers??[]).map((entry,index)=>{
    const patch=(changes:Partial<typeof entry>)=>onChange({...value,inventoryStageTransfers:(value.inventoryStageTransfers??[]).map((row,i)=>i===index?{...row,...changes}:row)})
    const stageOptions=[['raw-materials',t('مواد اولیه','Raw materials')],['work-in-progress',t('کالای در جریان ساخت','Work in progress')],['finished-goods',t('محصول نهایی','Finished goods')]] as const
    return <div className="fw-grid" key={entry.id}>
     <NumberField label={t('دوره','Period')} value={entry.period} onChange={v=>patch({period:v})}/>
     <label className="fw-field"><span>{t('مرحله مبدأ','Source stage')}</span><select value={entry.sourceStage??''} onChange={e=>patch({sourceStage:(e.target.value||null) as typeof entry.sourceStage})}><option value="">{t('انتخاب مرحله','Select stage')}</option>{stageOptions.map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label>
     <label className="fw-field"><span>{t('مرحله مقصد','Destination stage')}</span><select value={entry.destinationStage??''} onChange={e=>patch({destinationStage:(e.target.value||null) as typeof entry.destinationStage})}><option value="">{t('انتخاب مرحله','Select stage')}</option>{stageOptions.map(([key,label])=><option key={key} value={key}>{label}</option>)}</select></label>
     <TextField label={t('محصول مبدأ','Source product')} value={entry.sourceProductId} onChange={v=>patch({sourceProductId:v})}/>
     <TextField label={t('مرکز هزینه مبدأ','Source cost centre')} value={entry.sourceCostCentreId} onChange={v=>patch({sourceCostCentreId:v})}/>
     <TextField label={t('محصول مقصد','Destination product')} value={entry.destinationProductId} onChange={v=>patch({destinationProductId:v})}/>
     <TextField label={t('مرکز هزینه مقصد','Destination cost centre')} value={entry.destinationCostCentreId} onChange={v=>patch({destinationCostCentreId:v})}/>
     <NumberField label={t('مقدار مبدأ','Source quantity')} value={entry.quantity} onChange={v=>patch({quantity:v})}/>
     <TextField label={t('واحد مبدأ','Source unit')} value={entry.sourceUnit} onChange={v=>patch({sourceUnit:v})}/>
     <TextField label={t('واحد مقصد','Destination unit')} value={entry.destinationUnit} onChange={v=>patch({destinationUnit:v})}/>
     <NumberField label={t('ضریب تبدیل مقصد','Destination conversion factor')} value={entry.conversionFactor} onChange={v=>patch({conversionFactor:v})}/>
     <NumberField label={t('ارزش انتقال','Transferred value')} value={entry.transferValue} onChange={v=>patch({transferValue:v})}/>
     <TextField label={t('ارجاع سند / صفحه','Source document / page')} value={entry.sourceReference} onChange={v=>patch({sourceReference:v})}/>
     <label className="fw-field"><span>{t('وضعیت منبع','Source status')}</span><select value={entry.sourceVerified?'verified':'unverified'} onChange={e=>patch({sourceVerified:e.target.value==='verified'})}><option value="unverified">{t('تأییدنشده','Unverified')}</option><option value="verified">{t('تأییدشده','Verified')}</option></select></label>
     <button type="button" className="secondary-button" onClick={()=>onChange({...value,inventoryStageTransfers:(value.inventoryStageTransfers??[]).filter(row=>row.id!==entry.id)})}>{t('حذف انتقال','Remove transfer')}</button>
    </div>
   })}
   <button type="button" className="secondary-button" onClick={()=>onChange({...value,inventoryStageTransfers:[...(value.inventoryStageTransfers??[]),createBlankInventoryStageTransferFormDraft(crypto.randomUUID())]})}>{t('افزودن انتقال بین مراحل','Add inter-stage transfer')}</button>
  </div>
  <ProjectModelHelpCoveragePanel value={value.helpDriven} onChange={helpDriven=>onChange({...value,helpDriven})} language={language}/>
 </section>
}